// Seneschal lesson data (original content).
const COURSE = {"module":{"id":"voice-systems","title":"Voice Systems","lessons":[{"id":"ai-voice-assistant","title":"AI Voice Assistant"},{"id":"subagent-deep-worker","title":"Subagent: Deep Worker"},{"id":"s-dream","title":"S-DREAM"},{"id":"end-of-turn","title":"Knowing When You're Done"},{"id":"announcement-window","title":"The Announcement Window"},{"id":"eyes","title":"EYES — Visual Awareness"},{"id":"audio-ear","title":"The Ear — Audio Internals"}]},"lessons":{"ai-voice-assistant":{"id":"ai-voice-assistant","title":"AI Voice Assistant","summary":"Design a hands-free voice assistant for one user: streaming STT → LLM → TTS, a two-second latency budget, and a barge-in path that cancels the machine mid-sentence.","minutes":12,"level":"advanced","metrics":["total","util","backlog","delay"],"legend":[["msg","speech"],["req","text"],["res","tokens"],["kill","cancel"]],"goals":[{"text":"Break the ~2 s voice-to-voice budget into stage allowances","step":2},{"text":"Why streaming STT → LLM → TTS overlaps the stages","step":5},{"text":"GPU discipline: one job per GPU, voice stages on CPU","step":7},{"text":"How barge-in cancels the LLM and TTS on the first partial","step":9},{"text":"The full loop and its failure modes (echo, backlog)","step":10}],"steps":[{"short":"Meet Seneschal","chapter":"setup","title":"One user, zero screens","body":["Seneschal is a voice assistant for exactly one person. No accounts, no queues, no dashboard: you talk, it answers out loud, while your hands are busy.","That constraint shapes everything. A system with a single user cannot hide behind averages — every pause is <em>your</em> pause. The design goal is not scale, it is a conversation that feels natural."],"callout":{"kind":"insight","text":"Voice is a deadline disguised as a feature: the whole pipeline exists to answer before the silence gets awkward."},"metrics":{"total":null,"util":null,"backlog":null,"delay":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"hands busy","icon":"zap"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"BT · 16 kHz"},"spk":{"type":"block","x":-5,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]}},"links":{},"flows":[]}},{"short":"The 2 s budget","chapter":"problem","title":"Two seconds, or it feels broken","body":["Humans judge a voice conversation by round-trip feel. Below roughly two seconds between your last word and the machine’s first, it feels like a person thinking. Above that, it feels like a fax machine.","So we fix the budget first and design backwards from it. Every stage gets an allowance, and no stage is allowed to exceed it."],"callout":{"kind":"insight","text":"1.5–2 s voice-to-voice. Not p50 — every single turn."},"metrics":{"total":2000,"util":null,"backlog":null,"delay":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"hands busy","icon":"zap"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"BT · 16 kHz"},"spk":{"type":"block","x":-5,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"The voice budget","lines":["speech ends → intent     300 ms","ASR final transcript     350 ms","LLM first token          600 ms","first sentence ready     300 ms","TTS first audio          400 ms","= voice-to-voice       ~1950 ms","# under 2 s it feels like thinking"],"icon":"timer"}},"links":{},"flows":[]}},{"short":"Where it goes","chapter":"problem","title":"Five stages, five allowances","body":["The pipeline is a chain: microphone → streaming ASR → LLM → sentence splitter → TTS → speaker. Each hop adds latency, and they stack.","Capture and playback are nearly free (tens of ms). The big three are the ASR final transcript (~350 ms after you stop), the LLM first token (~600 ms) and the first TTS audio (~400 ms)."],"callout":{"kind":"insight","text":"Nothing here can be 10× faster. The win comes from overlapping stages, not speeding them up."},"metrics":{"total":2000,"util":95,"backlog":null,"delay":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"hands busy","icon":"zap"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"BT · 16 kHz"},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"streaming"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"streaming SSE"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"CPU · 82 M"},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"The voice budget","lines":["speech ends → intent     300 ms","ASR final transcript     350 ms","LLM first token          600 ms","first sentence ready     300 ms","TTS first audio          400 ms","= voice-to-voice       ~1950 ms","# under 2 s it feels like thinking"],"icon":"timer"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final transcript"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end","label":"sentences"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","label":"audio out"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.4},{"route":["asr","llm"],"kind":"req","rate":0.4},{"route":["llm","split"],"kind":"res","rate":2},{"route":["split","tts"],"kind":"msg","rate":0.7},{"route":["tts","spk"],"kind":"msg","rate":1.1}]}},{"short":"Hear the words","chapter":"technique","title":"Streaming ASR with server-side VAD","body":["Speech recognition runs as a stream: audio frames flow to the ASR service the whole time you speak, and it decides <b>when you stopped</b> — endpointing lives server-side, tuned on real pauses, not on a fixed client timeout.","While you talk, partial transcripts arrive and are shown live. The LLM is gated on the final transcript: one authoritative text per turn, so the model never answers a half-sentence."],"callout":{"kind":"insight","text":"Partials are for the eyes — and for barge-in. The final transcript is the only thing the brain hears."},"metrics":{"total":2000,"util":95,"backlog":null,"delay":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"speaking…","icon":"waves"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"BT · 16 kHz"},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"streaming · server VAD"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"waiting"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","style":"off","label":"waits for final"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":2.2}]}},{"short":"Think in tokens","chapter":"technique","title":"The LLM stream starts the clock","body":["The transcript goes to the LLM over a streaming connection. What matters is the <b>first</b> token, not the last: the answer starts existing the moment token one lands.","For voice, deep thinking is a trap — a model that reasons for eight seconds before speaking has already lost. Prefer a fast model with thinking low or off, and let the stream flow into the next stage token by token."],"callout":{"kind":"insight","text":"TTFT is the voice deadline. Total tokens just set how long the answer is."},"metrics":{"total":1700,"util":95,"backlog":null,"delay":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"speaking…","icon":"waves"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"final ready"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"streaming SSE","tags":[{"text":"thinking: low","tone":"amber","icon":"zap"}]},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","style":"off","label":"silence"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final transcript"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"}},"flows":[{"route":["asr","llm"],"kind":"req","rate":0.5},{"route":["llm","split"],"kind":"res","rate":2.4}]}},{"short":"First comma","chapter":"technique","title":"Speak at the first comma","body":["TTS never waits for the full answer. The splitter watches the token stream and cuts at the first sentence boundary; each finished sentence is synthesized immediately and queued to the speaker.","The first audio lands while the LLM is still writing sentence three. Perceived latency collapses because speaking and thinking overlap."],"callout":{"kind":"insight","text":"Sentence boundary = the unit of speech. Buffer until punctuation, synthesize immediately."},"metrics":{"total":1500,"util":95,"backlog":2,"delay":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"streaming SSE"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"CPU · 82 M"},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","style":"off"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end","label":"sentences"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","label":"audio out"}},"flows":[{"route":["llm","split"],"kind":"res","rate":2.4},{"route":["split","tts"],"kind":"msg","rate":0.9},{"route":["tts","spk"],"kind":"msg","rate":1.2}]}},{"short":"GPU discipline","chapter":"tradeoff","title":"One job per GPU, voice on CPU","body":["It is tempting to co-locate TTS on the LLM’s GPU. Don’t. Both stages spike together, the GPU context-switches, and the LLM’s token stream jitters — which is exactly the latency we spent five steps shaving.","The rule: the LLM owns a GPU with zero contention; every voice stage (capture, ASR, splitter, TTS) runs on CPU cores, which sit idle anyway while tokens stream."],"callout":{"kind":"insight","text":"No contention = no jitter. A dedicated GPU beats a shared faster one."},"metrics":{"total":1500,"util":60,"backlog":2,"delay":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"CPU"},"gpu":{"type":"zone","x0":-3.2,"x1":5.2,"y0":-3.4,"y1":3.4,"label":"GPU · LLM only"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"streaming SSE"},"cpu":{"type":"zone","x0":11.8,"x1":20.2,"y0":-3.4,"y1":3.4,"label":"CPU · voice"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"CPU · 82 M"},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","style":"off"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final transcript"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end","label":"sentences"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","label":"audio out"}},"flows":[{"route":["llm","split"],"kind":"res","rate":2.4},{"route":["split","tts"],"kind":"msg","rate":0.9},{"route":["tts","spk"],"kind":"msg","rate":1.2}]}},{"short":"Barge-in","chapter":"problem","title":"The user talks over the answer","body":["Real conversations are full duplex. You start talking while the assistant is mid-sentence — and a system that keeps talking is a system you interrupt with a finger on the mute button.","The failure mode: the TTS queue keeps playing, the LLM keeps generating, and your first words are buried under the machine’s last sentence."],"callout":{"kind":"insight","text":"In half duplex, silence is the machine’s job. Whoever owns the mic owns the floor."},"metrics":{"total":1500,"util":60,"backlog":3,"delay":"1.2 s"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"interrupting!","tone":"red","icon":"alert"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"hears you"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"still generating"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"CPU · 82 M","tags":[{"text":"TALKING","tone":"red","icon":"alert"}]},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","label":"keeps playing"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":2},{"route":["tts","spk"],"kind":"msg","rate":1.4},{"route":["split","tts"],"kind":"msg","rate":0.9}]}},{"short":"Cancel fast","chapter":"technique","title":"Cancel on the first partial","body":["The fix is brutal and simple: the <b>first</b> ASR partial after the answer started is a barge-in signal. It cancels the in-flight LLM request (even one just sent), drains the TTS queue and stops playback.","STT and VAD keep running the whole time — they are the ears, never cancelled. And a dispatched deep worker (memory consolidation) is fire-and-forget: it survives the interruption by design."],"callout":{"kind":"insight","text":"Barge-in is not pause. It is cancel-and-restart, with the ears never stopping."},"metrics":{"total":1500,"util":60,"backlog":0,"delay":"0 ms"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"interrupting!","tone":"red","icon":"alert"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"first partial"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"cancelled","tags":[{"text":"CANCELLED","tone":"red","icon":"close"}]},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"queue drained","tags":[{"text":"SILENT","tone":"green","icon":"check"}]},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","style":"off","label":"cancel"},"cb":{"from":"asr","to":"tts","pts":["asr","llm","split","tts"],"heads":"end","style":"cut","label":"cancel"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":2},{"route":["asr","llm"],"kind":"kill","rate":0.8},{"route":["asr","llm","split","tts"],"kind":"kill","rate":0.8}]}},{"short":"The whole loop","chapter":"insight","title":"Full loop, echo included","body":["One more failure mode: the speaker sits next to the microphone. Without echo cancellation the assistant hears its own voice, transcribes it, and answers itself — a loop.","The TTS output is fed to the echo canceller as a reference so the mic can subtract it. With that in place the loop closes: speak → transcript → tokens → sentences → audio → speak, with barge-in watching every partial."],"callout":{"kind":"insight","text":"A voice assistant is a control loop: sense (ASR) → decide (LLM) → act (TTS) — always listening."},"metrics":{"total":1500,"util":60,"backlog":0,"delay":"0 ms"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"+ AEC"},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"server VAD"},"gpu":{"type":"zone","x0":-3.2,"x1":5.2,"y0":-3.4,"y1":3.4,"label":"GPU · LLM only"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"streaming SSE"},"cpu":{"type":"zone","x0":11.8,"x1":20.2,"y0":-3.4,"y1":3.4,"label":"CPU · voice"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"CPU · 82 M"},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"aec":{"type":"ghost","x":15,"y":-11,"s":4,"h":34,"label":"echo reference: TTS → mic"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final transcript"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end","label":"sentences"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","label":"audio out"},"ref":{"from":"tts","to":"mic","pts":["tts","spk","mic"],"heads":"none","style":"off","label":"AEC reference"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.2},{"route":["asr","llm"],"kind":"req","rate":0.4},{"route":["llm","split"],"kind":"res","rate":2.2},{"route":["split","tts"],"kind":"msg","rate":0.9},{"route":["tts","spk"],"kind":"msg","rate":1.2}]}},{"short":"What we built","chapter":"recap","title":"Seneschal, end to end","body":["A single-user voice assistant with a two-second budget: server-side endpointing, a streaming LLM gated on the final transcript, sentence-level TTS on CPU, one GPU kept contention-free, and barge-in that cancels on the first partial.","Every design decision traces back to one number. When a conversation feels wrong, measure the stage that broke the budget — not the model, the stage."],"callout":{"kind":"insight","text":"Latency is a product feature. Budget it like one."},"metrics":{"total":1500,"util":60,"backlog":0,"delay":"0 ms"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"+ AEC"},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"server VAD"},"gpu":{"type":"zone","x0":-3.2,"x1":5.2,"y0":-3.4,"y1":3.4,"label":"GPU · LLM only"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["LLM"],"sub":"streaming SSE"},"cpu":{"type":"zone","x0":11.8,"x1":20.2,"y0":-3.4,"y1":3.4,"label":"CPU · voice"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"CPU · 82 M"},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"What we built","lines":["endpointing      server-side","LLM gate         final transcript","TTS unit         sentence","GPU              1 job only","barge-in         first partial","ears             never cancelled","# budget: ~2 s voice-to-voice"],"icon":"check"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final transcript"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end","label":"sentences"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","label":"audio out"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.2},{"route":["asr","llm"],"kind":"req","rate":0.4},{"route":["llm","split"],"kind":"res","rate":2.2},{"route":["split","tts"],"kind":"msg","rate":0.9},{"route":["tts","spk"],"kind":"msg","rate":1.2}]}}]},"subagent-deep-worker":{"id":"subagent-deep-worker","title":"Subagent: Deep Worker","summary":"Give the voice model a butler: one lean talker, one deep worker with its own LLM, thinking and toolbox — detached execution that survives barge-in and results that land as a single spoken announcement.","minutes":10,"level":"advanced","metrics":["delay","workers","lost","util"],"legend":[["msg","speech"],["write","task"],["res","tokens"],["kill","cancel"]],"goals":[{"text":"Why the voice model must stay lean (few tools, no thinking)","step":2},{"text":"How run_deep_task hands off work with an immediate ack","step":4},{"text":"The worker's loop: plan with thinking, execute with tools","step":5},{"text":"Detached execution: what cancels the worker and what never does","step":9},{"text":"Results arrive as one announcement, never a tool log","step":10}],"steps":[{"short":"Meet the worker","chapter":"setup","title":"The voice model needs a butler","body":["Seneschal answers in under two seconds, but some requests are not conversation: «research this and summarize», «check the build logs», «look at my screen». Heavy work needs thinking, tools and time — none of which the voice loop can afford.","The fix is not a bigger voice model. It is a second one: a deep worker running inside the same process, with its own LLM endpoint, its own tool loop and its own toolbox — reachable from the voice model through a single tool: <code>run_deep_task</code>."],"callout":{"kind":"insight","text":"One lean talker, one deep thinker. The voice model delegates; it never does the heavy lifting."},"metrics":{"delay":null,"workers":null,"lost":null,"util":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"hands busy","icon":"zap"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"BT · 16 kHz"},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"server VAD"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"streaming SSE"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"CPU · 82 M"},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final transcript"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end","label":"sentences"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","label":"audio out"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.2},{"route":["llm","split"],"kind":"res","rate":2},{"route":["split","tts"],"kind":"msg","rate":0.7},{"route":["tts","spk"],"kind":"msg","rate":1}]}},{"short":"Saturate the talker","chapter":"problem","title":"Heavy tools, slow talker","body":["Give the voice model every tool — MCP servers, files, shell, search — and every turn pays for it: a bigger system prompt, more schemas to parse, slower first token. Add thinking and the pause before the first word grows to seconds.","Worse: a tool loop in the voice lane stalls the conversation. You asked for research; you get silence while the model calls tools one by one."],"callout":{"kind":"insight","text":"Every tool you add to the voice model is paid on every single turn."},"metrics":{"delay":"45 s","workers":0,"lost":null,"util":95},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"waiting…","tone":"red","icon":"hourglass"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"tool loop · thinking","tags":[{"text":"TOOLS ×20","tone":"amber","icon":"box"},{"text":"THINKING","tone":"red","icon":"bulb"}]},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"idle"},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"tags":[{"text":"SILENT","tone":"red","icon":"alert"}]},"mcp":{"type":"block","x":-5,"y":9,"color":"yellow","glyph":"network","label":["MCP"]},"files":{"type":"block","x":-1,"y":9,"color":"yellow","glyph":"file","label":["Files"]},"shell":{"type":"block","x":3,"y":9,"color":"yellow","glyph":"code","label":["Shell"]},"search":{"type":"block","x":7,"y":9,"color":"yellow","glyph":"search","label":["Search"]},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"Voice lane under load","lines":["system prompt       huge (tool schemas)","first token          +thinking pass","tool loop            stalls speech","user waits           ~45 s of silence","# conversation dead while tools run"],"icon":"timer"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","style":"off"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final transcript"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","style":"off"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end","style":"off"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","style":"off"},"t1":{"from":"mcp","to":"llm","pts":["mcp","llm"],"heads":"end","style":"beat"},"t2":{"from":"files","to":"llm","pts":["files","llm"],"heads":"end","style":"beat"},"t3":{"from":"shell","to":"llm","pts":["shell","llm"],"heads":"end","style":"beat"},"t4":{"from":"search","to":"llm","pts":["search","llm"],"heads":"end","style":"beat"}},"flows":[{"route":["mcp","llm"],"kind":"req","rate":0.8},{"route":["files","llm"],"kind":"req","rate":0.8},{"route":["shell","llm"],"kind":"req","rate":0.8},{"route":["search","llm"],"kind":"req","rate":0.8}]}},{"short":"Delegate it all","chapter":"insight","title":"Delegate, don’t saturate","body":["The principle: the speech model keeps a tiny toolkit — voice in, voice out, and <b>one</b> delegation tool. Everything else moves to the worker’s pool, where latency is measured in quality, not in time-to-first-token.","The voice model stays fast because it stays lean; the worker gets to think because nobody is standing next to it with a stopwatch."],"callout":{"kind":"insight","text":"run_deep_task is the only bridge. The voice model never sees the worker’s tools."},"metrics":{"delay":null,"workers":0,"lost":null,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"lean · 2 tools","tags":[{"text":"voice + run_deep_task","tone":"green","icon":"check"}]},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"]},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"worker":{"type":"block","x":1,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"own endpoint"}},"links":{"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"},"task":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"both","style":"off","label":"run_deep_task"}},"flows":[{"route":["llm","split"],"kind":"res","rate":2}]}},{"short":"The handoff","chapter":"technique","title":"Ack first, result later","body":["When the voice model decides to delegate, it calls <code>run_deep_task(task)</code>. The reply is immediate: an ack — «I’m on it» — is spoken, a process sound plays, and a shortened exchange is persisted. No tool results ever enter the speech history.","The task itself runs in the background. The conversation continues as if nothing happened — because for the voice loop, nothing did."],"callout":{"kind":"insight","text":"Ack first, result later. The user hears the commitment, not the wait."},"metrics":{"delay":"0 ms","workers":1,"lost":null,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"lean · 2 tools"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"]},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"worker":{"type":"block","x":1,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"running…","tags":[{"text":"TASK #1","tone":"amber","icon":"play"}]}},"links":{"task":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"end","label":"run_deep_task"},"ack":{"from":"worker","to":"spk","pts":["worker","split","tts","spk"],"heads":"end","style":"off","label":"ack · «on it»"}},"flows":[{"route":["llm","worker"],"kind":"write","rate":0.8},{"route":["worker","split","tts","spk"],"kind":"msg","rate":0.7}]}},{"short":"Inside the worker","chapter":"technique","title":"Plan, then loop","body":["The worker thinks before it acts: pass one plans with thinking enabled and no tools; pass two executes the plan in a tool-calling loop. The plan keeps the loop honest; the loop keeps the plan grounded.","When the work is done, the final answer is synthesized <b>for voice</b> — short, spoken-form, no markdown debris. The speech model never sees the intermediate steps."],"callout":{"kind":"insight","text":"Two passes beat one: plan with thinking, execute without."},"metrics":{"delay":"0 ms","workers":1,"lost":null,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"llm":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"lean"},"split":{"type":"block","x":1,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":8,"y":0,"color":"orange","glyph":"volume2","label":["TTS"]},"spk":{"type":"block","x":15,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"worker":{"type":"block","x":-6,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"own endpoint · thinking"},"plan":{"type":"ghost","x":1,"y":6,"s":4,"h":34,"label":"pass 1: plan (thinking, no tools)"},"loop":{"type":"ghost","x":8,"y":6,"s":4,"h":34,"label":"pass 2: tool loop (no thinking)"}},"links":{"task":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"end","style":"off"},"w1":{"from":"worker","to":"loop","pts":["worker","loop"],"heads":"end","label":"tools"},"w2":{"from":"loop","to":"plan","pts":["loop","plan"],"heads":"end","style":"off","label":"synthesis"}},"flows":[{"route":["worker","loop"],"kind":"req","rate":1},{"route":["loop","plan"],"kind":"res","rate":0.8}]}},{"short":"Private toolbox","chapter":"technique","title":"A toolbox the voice never sees","body":["The worker loads what the voice model must not: MCP servers, file tools, shell, screen capture, web search — plus the prompt sections of its plugins. The speech model’s prompt stays tiny, so its first token stays fast.","Vision goes to the worker’s endpoint too: screenshots are read by the deep model, not by the talker."],"callout":{"kind":"insight","text":"Heavy tools are a subscription the voice model stops paying."},"metrics":{"delay":"0 ms","workers":1,"lost":null,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"llm":{"type":"block","x":-13,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"lean · 2 tools"},"tts":{"type":"block","x":-5,"y":0,"color":"orange","glyph":"volume2","label":["TTS"]},"spk":{"type":"block","x":2,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"pool":{"type":"zone","x0":-7.5,"x1":9.5,"y0":5.4,"y1":13.2,"label":"WORKER POOL · own endpoint"},"worker":{"type":"block","x":1,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"thinking ON"},"mcp":{"type":"block","x":-5,"y":15,"color":"yellow","glyph":"network","label":["MCP"]},"files":{"type":"block","x":-1,"y":15,"color":"yellow","glyph":"file","label":["Files"]},"shell":{"type":"block","x":3,"y":15,"color":"yellow","glyph":"code","label":["Shell"]},"search":{"type":"block","x":7,"y":15,"color":"yellow","glyph":"search","label":["Search"]}},"links":{"t1":{"from":"mcp","to":"worker","pts":["mcp","worker"],"heads":"end"},"t2":{"from":"files","to":"worker","pts":["files","worker"],"heads":"end"},"t3":{"from":"shell","to":"worker","pts":["shell","worker"],"heads":"end"},"t4":{"from":"search","to":"worker","pts":["search","worker"],"heads":"end"}},"flows":[{"route":["mcp","worker"],"kind":"res","rate":0.7},{"route":["files","worker"],"kind":"res","rate":0.7},{"route":["search","worker"],"kind":"res","rate":0.7}]}},{"short":"Nested delegation","chapter":"technique","title":"Subagents under one voice","body":["Some jobs are still too big for one loop. The worker can call <code>run_agent</code> and hand a task to an external subagent — Hermes over ACP — reusing the same handles and sessions.","Delegation all the way down: the voice delegates to the worker, the worker delegates to the fleet. Each layer has its own budget, its own model, its own deadline."],"callout":{"kind":"insight","text":"Voice → worker → subagents. One conversation, many workers."},"metrics":{"delay":"0 ms","workers":2,"lost":null,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"llm":{"type":"block","x":-13,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"lean"},"tts":{"type":"block","x":-5,"y":0,"color":"orange","glyph":"volume2","label":["TTS"]},"spk":{"type":"block","x":2,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"worker":{"type":"block","x":1,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"thinking ON"},"agent":{"type":"block","x":9,"y":9,"color":"green","glyph":"bot","label":["Subagent"],"sub":"Hermes · ACP","tags":[{"text":"TASK #2","tone":"green","icon":"play"}]}},"links":{"task":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"end","style":"off"},"del":{"from":"worker","to":"agent","pts":["worker","agent"],"heads":"end","label":"run_agent"}},"flows":[{"route":["llm","worker"],"kind":"write","rate":0.6},{"route":["worker","agent"],"kind":"write","rate":0.6}]}},{"short":"Barge-in conflict","chapter":"problem","title":"The user talks over the task","body":["The user interrupts mid-announcement. The naive reflex — cancel everything in flight — kills the research task that has been running for two minutes. Work lost, user annoyed, and the same request will be paid for twice.","Speech cancellation and work cancellation are different decisions. Confusing them is the bug."],"callout":{"kind":"insight","text":"The ears cancel speech. They must not cancel work."},"metrics":{"delay":"0 ms","workers":1,"lost":1,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"interrupting!","tone":"red","icon":"alert"}]},"llm":{"type":"block","x":-13,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"cancelled","tags":[{"text":"CANCELLED","tone":"red","icon":"close"}]},"tts":{"type":"block","x":-5,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"sub":"queue drained","tags":[{"text":"SILENT","tone":"green","icon":"check"}]},"spk":{"type":"block","x":2,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"worker":{"type":"block","x":1,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"2 min of work…","tags":[{"text":"CANCELLED","tone":"red","icon":"close"}]}},"links":{"task":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"end","style":"off"},"kill":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"end","style":"cut","label":"cancel"}},"flows":[{"route":["llm","worker"],"kind":"kill","rate":1}]}},{"short":"Detached by design","chapter":"technique","title":"Speech is interruptible; work is not","body":["The deep task is <b>detached</b>: barge-in cancels the LLM stream and the TTS queue, never the worker. Concurrent units coexist — you can hand off a second task while the first is still running.","The only cancellations are explicit: the inline <code>cancel</code> command from voice, the task timeout, and process shutdown. Everything else keeps working while you talk about something else."],"callout":{"kind":"insight","text":"Barge-in is for the mouth and the ears. The worker has neither."},"metrics":{"delay":"0 ms","workers":2,"lost":0,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"interrupting!","tone":"red","icon":"alert"}]},"llm":{"type":"block","x":-13,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"cancelled"},"tts":{"type":"block","x":-5,"y":0,"color":"orange","glyph":"volume2","label":["TTS"],"tags":[{"text":"SILENT","tone":"green","icon":"check"}]},"spk":{"type":"block","x":2,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"worker":{"type":"block","x":1,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"unaffected","tags":[{"text":"TASK #1 · 2 min","tone":"green","icon":"play"}]},"worker2":{"type":"block","x":9,"y":9,"color":"violet","glyph":"cpu","label":["Worker #2"],"sub":"coexists","tags":[{"text":"TASK #2","tone":"amber","icon":"play"}]}},"links":{"task":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"end","style":"off","label":"keeps running"}},"flows":[{"route":["llm","worker"],"kind":"write","rate":0.5},{"route":["llm","worker"],"kind":"write","rate":0.5}]}},{"short":"One announcement","chapter":"insight","title":"The result speaks once","body":["When the result is ready it arrives as a proactive event with no tool identity, waits for a natural opening in the announcement window, and is spoken as <b>one locution</b> — never fragmented across turns.","The speech history sees a clean sentence, not a tool log. The machinery stays invisible: you asked in one sentence, you get one sentence back."],"callout":{"kind":"insight","text":"The user asked in one sentence and gets one sentence back. The machinery stays invisible."},"metrics":{"delay":"0 ms","workers":2,"lost":0,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"llm":{"type":"block","x":-13,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"lean"},"tts":{"type":"block","x":-5,"y":0,"color":"orange","glyph":"volume2","label":["TTS"]},"spk":{"type":"block","x":2,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"tags":[{"text":"ANNOUNCING","tone":"green","icon":"volume2"}]},"worker":{"type":"block","x":1,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"done","tags":[{"text":"RESULT READY","tone":"green","icon":"circleCheck"}]},"win":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"Announcement window","lines":["proactive event     no tool_call_id","waits for           natural pause","spoken as           ONE locution","speech history      clean sentence","# never a tool log"],"icon":"message"}},"links":{"task":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"end","style":"off"},"res":{"from":"worker","to":"spk","pts":["worker","spk"],"heads":"end","label":"single locution"}},"flows":[{"route":["worker","spk"],"kind":"msg","rate":0.9}]}},{"short":"What we built","chapter":"recap","title":"A butler for the voice","body":["A lean voice model with one delegation tool, a deep worker with its own endpoint, thinking and toolbox, detached execution that survives barge-in, and results that land as a single spoken announcement.","The voice model stays fast because it stays lean. The worker stays honest because it plans before it acts. And the user never waits for either."],"callout":{"kind":"insight","text":"Delegate the heavy, keep the light. That is the whole pattern."},"metrics":{"delay":"0 ms","workers":2,"lost":0,"util":40},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"server VAD"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"lean · 2 tools"},"split":{"type":"block","x":8,"y":0,"color":"orange","glyph":"split","label":["Sentence","Splitter"]},"tts":{"type":"block","x":15,"y":0,"color":"orange","glyph":"volume2","label":["TTS"]},"spk":{"type":"block","x":22,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"worker":{"type":"block","x":1,"y":9,"color":"violet","glyph":"cpu","label":["Deep Worker"],"sub":"own endpoint · thinking"},"agent":{"type":"block","x":9,"y":9,"color":"green","glyph":"bot","label":["Subagent"],"sub":"Hermes · ACP"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"What we built","lines":["voice tools      voice + run_deep_task","worker LLM       own endpoint · thinking","loop             plan → tools → speak","barge-in         never cancels work","results          ONE announcement","# the voice model stays lean"],"icon":"check"}},"links":{"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final transcript"},"c":{"from":"llm","to":"split","pts":["llm","split"],"heads":"end","label":"tokens"},"d":{"from":"split","to":"tts","pts":["split","tts"],"heads":"end","label":"sentences"},"e":{"from":"tts","to":"spk","pts":["tts","spk"],"heads":"end","label":"audio out"},"task":{"from":"llm","to":"worker","pts":["llm","worker"],"heads":"end","label":"run_deep_task"},"del":{"from":"worker","to":"agent","pts":["worker","agent"],"heads":"end","label":"run_agent"},"res":{"from":"worker","to":"spk","pts":["worker","split","tts","spk"],"heads":"end","style":"off","label":"announcement"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.2},{"route":["llm","split"],"kind":"res","rate":1.8},{"route":["split","tts"],"kind":"msg","rate":0.7},{"route":["tts","spk"],"kind":"msg","rate":1},{"route":["llm","worker"],"kind":"write","rate":0.5},{"route":["worker","agent"],"kind":"write","rate":0.4}]}}]},"s-dream":{"id":"s-dream","title":"S-DREAM","summary":"While you sleep, S-DREAM archives the day’s conversation and distills it into facts, memories and summaries — an append-only archive, immutable corrections, and recall through full-text search.","minutes":10,"level":"advanced","metrics":["util","fresh","rows","storage"],"legend":[["write","export"],["res","distill"],["msg","recall"],["kill","compact"]],"goals":[{"text":"Why a finite context window needs a cold tier","step":2},{"text":"The idle + message-count gate before a cycle runs","step":4},{"text":"Append-only JSONL export with rotation","step":5},{"text":"The three distillation passes and their outputs","step":6},{"text":"Corrections become immutable facts that survive compaction","step":7},{"text":"How recall works: prompt injection plus FTS5 search","step":9}],"steps":[{"short":"The forgetting problem","chapter":"setup","title":"A memory that resets at dawn","body":["A voice assistant that forgets you every morning is a clock radio. The context window holds minutes of conversation; a life together needs years. Where does all of it go when the window is finite?","Seneschal’s answer is S-DREAM — <b>S</b>cheduled DREAM — a consolidation daemon living in its own crate. While you are away, it archives what was said and distills it into the few facts and memories that will matter tomorrow."],"callout":{"kind":"insight","text":"The voice loop must never pay for memory. Consolidation happens off the hot path, while nobody is talking."},"metrics":{"util":95,"fresh":"stale","rows":null,"storage":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"asleep","icon":"moon"}]},"ctx":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"layers","label":["Context","Window"],"sub":"hot · finite"},"db":{"type":"db","x":2,"y":0,"label":"messages · hot"}},"links":{"a":{"from":"ctx","to":"db","pts":["ctx","db"],"heads":"both","label":"history"}},"flows":[]}},{"short":"A window that fills","chapter":"problem","title":"Ninety-five percent is the past","body":["Every turn pushes the window closer to its limit. At 95% utilization the model spends most of its attention on old turns — and when the window finally overflows, the oldest conversations don’t move anywhere. They stop existing.","Worse: the history you want tomorrow (“what did we decide about the garage door?”) is exactly the history the window dropped last week."],"callout":{"kind":"insight","text":"History that has nowhere to go is history you will lose."},"metrics":{"util":95,"fresh":"stale","rows":null,"storage":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"ctx":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"layers","label":["Context","Window"],"sub":"hot · finite","tags":[{"text":"95% FULL","tone":"red","icon":"alert"}]},"db":{"type":"db","x":2,"y":0,"label":"messages · hot"},"gone":{"type":"ghost","x":2,"y":9,"s":4,"h":34,"label":"turns #1–#40: nowhere to go"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"Context window","lines":["system prompt        fixed","memories + facts     fixed","conversation         grows","                     ↓","oldest turns         dropped","# dropped = lost forever"],"icon":"layers"}},"links":{"a":{"from":"ctx","to":"db","pts":["ctx","db"],"heads":"both","style":"off","label":"overflow"}},"flows":[]}},{"short":"Two tiers","chapter":"insight","title":"L1 hot, L2 cold","body":["The fix is the pattern every memory system converges on: two tiers. <b>L1</b> is hot — the context window plus a small set of active memories injected into the prompt. <b>L2</b> is cold — an append-only archive, full-text searchable, plus distilled facts, memories and session summaries.","It is the same trade your own sleep makes: the day’s raw experience is distilled overnight into the few things worth keeping. S-DREAM is that sleep."],"callout":{"kind":"insight","text":"L1 answers now. L2 answers eventually — but it answers forever."},"metrics":{"util":null,"fresh":"stale","rows":null,"storage":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"l1":{"type":"zone","x0":-8.6,"x1":-3.4,"y0":-3.2,"y1":3.2,"label":"L1 · HOT"},"ctx":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"layers","label":["Context","Window"],"sub":"hot · finite"},"db":{"type":"db","x":2,"y":0,"label":"messages · hot"},"l2":{"type":"zone","x0":-7.6,"x1":11.6,"y0":5.4,"y1":18.6,"label":"L2 · COLD"},"arch":{"type":"block","x":-5,"y":9,"color":"yellow","glyph":"file","label":["JSONL","archive"],"sub":"append-only"},"dream":{"type":"block","x":2,"y":9,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"daemon"},"llm":{"type":"block","x":9,"y":9,"color":"violet","glyph":"bot","label":["Distiller"],"sub":"complete()"},"facts":{"type":"block","x":-5,"y":15,"color":"orange","glyph":"database","label":["Profile","facts"]},"mem":{"type":"block","x":1,"y":15,"color":"green","glyph":"layers","label":["Memories"]},"sum":{"type":"block","x":7,"y":15,"color":"green","glyph":"scroll","label":["Summaries"]}},"links":{"a":{"from":"ctx","to":"db","pts":["ctx","db"],"heads":"both","style":"off"}},"flows":[]}},{"short":"The gate","chapter":"technique","title":"Consolidate only when it is safe","body":["S-DREAM is a loop, but a polite one. Before every cycle it checks two gates: the user must be <b>idle</b> (600 s by default — it never distills a live conversation mid-thought) and there must be enough <b>new messages</b> (50 by default — it never distills nothing).","If neither interval nor gates apply, there is one more option: a scheduled hour. By default the cycle runs at 03:00, while the house sleeps."],"callout":{"kind":"insight","text":"The daemon earns its keep by knowing when not to run."},"metrics":{"util":null,"fresh":"stale","rows":null,"storage":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"idle 600 s","tone":"green","icon":"check"}]},"db":{"type":"db","x":2,"y":0,"label":"messages · hot"},"dream":{"type":"block","x":2,"y":9,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"checking gates","tags":[{"text":"idle ✓","tone":"green","icon":"check"},{"text":"≥ 50 msgs ✓","tone":"green","icon":"check"}]},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"Cycle gate","lines":["on_idle             600 s","new messages        ≥ 50","scheduled_hour      03:00","# else: skip, sleep on"],"icon":"clock"}},"links":{"a":{"from":"dream","to":"db","pts":["dream","db"],"heads":"end","style":"off","label":"may I?"}},"flows":[]}},{"short":"Export first","chapter":"technique","title":"Archive everything, delete nothing","body":["Stage one is mechanical and safe: append every message since the last processed timestamp to a dated JSONL file — one JSON object per line, session, timestamp, role, content. No LLM involved.","Files rotate at 10 MB or 10,000 lines into <code>.001.jsonl</code>, <code>.002.jsonl</code>… and old files are <b>never deleted</b>. The archive is sacred: distillation can be re-run and improved; the raw history cannot be reconstructed."],"callout":{"kind":"insight","text":"Distill carelessly, archive carefully. You can re-think the past only if you kept it."},"metrics":{"util":40,"fresh":"stale","rows":50,"storage":"2 MB"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"db":{"type":"db","x":2,"y":0,"label":"messages · hot"},"dream":{"type":"block","x":2,"y":9,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"stage 1 · export"},"arch":{"type":"block","x":-5,"y":9,"color":"yellow","glyph":"file","label":["JSONL","archive"],"sub":"append-only"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"Rotation","lines":["2026-07-28.jsonl","  10 MB or 10 000 lines","  → 2026-07-28.001.jsonl","  → 2026-07-28.002.jsonl","# old files never deleted"],"icon":"file"}},"links":{"a":{"from":"db","to":"dream","pts":["db","dream"],"heads":"end","label":"new messages only"},"b":{"from":"dream","to":"arch","pts":["dream","arch"],"heads":"end","label":"append"}},"flows":[{"route":["db","dream"],"kind":"write","rate":1.2},{"route":["dream","arch"],"kind":"write","rate":1.2}]}},{"short":"Distill","chapter":"technique","title":"Three passes make a memory","body":["Stage two is the LLM’s shift. Three passes over the new conversation text: <code>extract_facts</code> upserts profile facts with a confidence score; <code>extract_memories</code> adds new memories and <b>archives outdated ones</b> (the prompt receives the existing list, so it deduplicates instead of repeating); <code>generate_summary</code> writes a 2–4 sentence summary in the conversation’s own language, bound to the message id it covers.","Categories keep memories honest: project, decision, preference, relationship — or they are small talk, and small talk is not memory."],"callout":{"kind":"insight","text":"Facts say who you are. Memories say what happened. Summaries say what it meant."},"metrics":{"util":40,"fresh":"stale","rows":50,"storage":"2 MB"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"dream":{"type":"block","x":2,"y":9,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"stage 2 · distill"},"arch":{"type":"block","x":-5,"y":9,"color":"yellow","glyph":"file","label":["JSONL","archive"]},"llm":{"type":"block","x":9,"y":9,"color":"violet","glyph":"bot","label":["Distiller"],"sub":"complete()"},"facts":{"type":"block","x":-5,"y":15,"color":"orange","glyph":"database","label":["Profile","facts"],"sub":"upsert · conf 0–1"},"mem":{"type":"block","x":1,"y":15,"color":"green","glyph":"layers","label":["Memories"],"sub":"add · archive"},"sum":{"type":"block","x":7,"y":15,"color":"green","glyph":"scroll","label":["Summaries"],"sub":"2–4 sentences"}},"links":{"a":{"from":"dream","to":"llm","pts":["dream","llm"],"heads":"end","label":"conversation text"},"f1":{"from":"llm","to":"facts","pts":["llm","facts"],"heads":"end","label":"facts"},"f2":{"from":"llm","to":"mem","pts":["llm","mem"],"heads":"end","label":"memories"},"f3":{"from":"llm","to":"sum","pts":["llm","sum"],"heads":"end","label":"summary"}},"flows":[{"route":["dream","llm"],"kind":"res","rate":1},{"route":["llm","facts"],"kind":"res","rate":0.7},{"route":["llm","mem"],"kind":"res","rate":0.7},{"route":["llm","sum"],"kind":"res","rate":0.7}]}},{"short":"Corrections","chapter":"technique","title":"“No — it’s X” becomes law","body":["Stage three scans the last 50 messages for one specific speech act: the <b>correction</b>. When you say “no, it’s actually Tuesday”, the old fact is not just wrong — it is dangerous.","Corrections are saved as <code>correction:&lt;topic&gt;</code> facts with confidence 1.0 and treated as immutable rules. Every later stage of consolidation, however aggressive, must respect them."],"callout":{"kind":"insight","text":"A correction is the user editing the database by voice. It outranks the machine."},"metrics":{"util":40,"fresh":"stale","rows":50,"storage":"2 MB"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"“no, it’s X”","tone":"red","icon":"alert"}]},"dream":{"type":"block","x":2,"y":9,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"stage 3 · corrections"},"llm":{"type":"block","x":9,"y":9,"color":"violet","glyph":"bot","label":["Distiller"]},"facts":{"type":"block","x":-5,"y":15,"color":"orange","glyph":"database","label":["Profile","facts"],"sub":"correction:* · conf 1.0","tags":[{"text":"IMMUTABLE","tone":"green","icon":"shield"}]},"mem":{"type":"block","x":1,"y":15,"color":"green","glyph":"layers","label":["Memories"]},"sum":{"type":"block","x":7,"y":15,"color":"green","glyph":"scroll","label":["Summaries"]}},"links":{"a":{"from":"you","to":"dream","pts":["you","dream"],"heads":"end","style":"off","label":"last 50 msgs"},"f1":{"from":"llm","to":"facts","pts":["llm","facts"],"heads":"end","label":"correction:<topic>"}},"flows":[{"route":["llm","facts"],"kind":"write","rate":0.8}]}},{"short":"Compaction","chapter":"tradeoff","title":"Memory must forget too","body":["Stage four is housekeeping: facts whose confidence has decayed below 0.3 are deleted — except corrections and immutable rules. Without this, the profile grows monotonically: yesterday’s stale job, an old address, a abandoned project, all competing for prompt space.","The trade-off is real. Compact hard and you lose nuance you might have wanted; compact softly and the profile rots into noise. Confidence decay is the dial between the two."],"callout":{"kind":"insight","text":"A profile that only grows is not memory. It is a landfill."},"metrics":{"util":40,"fresh":"stale","rows":50,"storage":"2 MB"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"dream":{"type":"block","x":2,"y":9,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"stage 4 · compact"},"facts":{"type":"block","x":-5,"y":15,"color":"orange","glyph":"database","label":["Profile","facts"],"sub":"conf < 0.3 → gone","tags":[{"text":"compact","tone":"amber","icon":"filter"}]},"stale":{"type":"ghost","x":1,"y":21,"s":4,"h":34,"label":"old job@X · conf 0.2 — deleted"},"corr":{"type":"block","x":7,"y":15,"color":"green","glyph":"shield","label":["Immutable","rules"],"sub":"never compacted"}},"links":{"a":{"from":"dream","to":"facts","pts":["dream","facts"],"heads":"end","label":"DELETE conf < 0.3"},"b":{"from":"facts","to":"stale","pts":["facts","stale"],"heads":"end","style":"cut","label":"gone"}},"flows":[{"route":["facts","stale"],"kind":"kill","rate":0.8}]}},{"short":"Recall","chapter":"technique","title":"Remembering on demand","body":["Cold storage is worthless without a warm path back. Recall works at two depths. Every turn, active memories and profile facts are injected into the system prompt — cheap, always on. And for anything deeper, the model has the <code>recover_historical_context</code> tool: FTS5 full-text search with BM25 ranking over messages, memories and summaries.","The assistant can thus answer “what did we decide about the garage door?” — not because it remembers, but because it knows how to look."],"callout":{"kind":"insight","text":"Injected memory is what you always know. Searched memory is what you can find out."},"metrics":{"util":40,"fresh":"fresh","rows":1200,"storage":"84 MB"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"ctx":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"layers","label":["Context","Window"],"sub":"prompt + memories"},"db":{"type":"db","x":2,"y":0,"label":"messages · hot"},"arch":{"type":"block","x":-5,"y":9,"color":"yellow","glyph":"file","label":["JSONL","archive"],"sub":"FTS5"},"facts":{"type":"block","x":-5,"y":15,"color":"orange","glyph":"database","label":["Profile","facts"]},"mem":{"type":"block","x":1,"y":15,"color":"green","glyph":"layers","label":["Memories"]},"sum":{"type":"block","x":7,"y":15,"color":"green","glyph":"scroll","label":["Summaries"]}},"links":{"r1":{"from":"mem","to":"ctx","pts":["mem","ctx"],"heads":"end","label":"prompt inject"},"r2":{"from":"arch","to":"ctx","pts":["arch","ctx"],"heads":"end","style":"off","label":"FTS5 · BM25"},"r3":{"from":"sum","to":"ctx","pts":["sum","ctx"],"heads":"end","style":"off"}},"flows":[{"route":["mem","ctx"],"kind":"msg","rate":0.8},{"route":["arch","ctx"],"kind":"msg","rate":0.8}]}},{"short":"Graceful by design","chapter":"insight","title":"Degrade, never block","body":["S-DREAM shares nothing with the voice loop’s deadlines. It runs on CPU, off the hot path, and if there is no LLM client at all, stage one — the archive — still runs; only distillation is skipped. The past keeps accumulating either way.","And for the impatient: <code>--dream</code> runs a single cycle on demand. Memory is a background daemon until you want it right now."],"callout":{"kind":"insight","text":"Archive first, distill later. A missing brain must never cost you the raw history."},"metrics":{"util":40,"fresh":"fresh","rows":1200,"storage":"84 MB"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"talking","icon":"waves"}]},"voice":{"type":"zone","x0":-8.6,"x1":5.4,"y0":-3.2,"y1":3.2,"label":"VOICE LOOP · hot path"},"ctx":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"layers","label":["Context","Window"]},"db":{"type":"db","x":2,"y":0,"label":"messages"},"dream":{"type":"block","x":2,"y":9,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"CPU · background","tags":[{"text":"never blocks voice","tone":"green","icon":"check"}]},"arch":{"type":"block","x":-5,"y":9,"color":"yellow","glyph":"file","label":["JSONL","archive"]}},"links":{"a":{"from":"ctx","to":"db","pts":["ctx","db"],"heads":"end","style":"off"},"b":{"from":"dream","to":"arch","pts":["dream","arch"],"heads":"end","label":"works with or without LLM"}},"flows":[{"route":["dream","arch"],"kind":"write","rate":0.9}]}},{"short":"What we built","chapter":"recap","title":"You sleep, it consolidates","body":["A gated daemon that archives every message to an append-only JSONL store, distills it into facts, memories and summaries, elevates your corrections to immutable law, compacts the rest by confidence, and hands it all back through prompt injection and full-text search.","The context window stays small and fast. The memory stays large and true. And the conversation never has to know either one exists."],"callout":{"kind":"insight","text":"Memory is not remembering everything. It is knowing where everything went."},"metrics":{"util":40,"fresh":"fresh","rows":1200,"storage":"84 MB"},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"ctx":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"layers","label":["Context","Window"],"sub":"L1 · hot"},"db":{"type":"db","x":2,"y":0,"label":"messages"},"dream":{"type":"block","x":2,"y":9,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"idle 600 s · ≥50 msgs · 03:00"},"arch":{"type":"block","x":-5,"y":9,"color":"yellow","glyph":"file","label":["JSONL","archive"],"sub":"append-only"},"llm":{"type":"block","x":9,"y":9,"color":"violet","glyph":"bot","label":["Distiller"],"sub":"3 passes"},"facts":{"type":"block","x":-5,"y":15,"color":"orange","glyph":"database","label":["Facts"],"sub":"conf 0–1"},"mem":{"type":"block","x":1,"y":15,"color":"green","glyph":"layers","label":["Memories"],"sub":"add · archive"},"sum":{"type":"block","x":7,"y":15,"color":"green","glyph":"scroll","label":["Summaries"],"sub":"FTS5"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"What we built","lines":["gate         idle + ≥50 msgs","schedule     03:00 daily","archive      JSONL · never delete","distill      facts · memories · summary","corrections  immutable · conf 1.0","recall       prompt inject + FTS5","# you sleep, it consolidates"],"icon":"moon"}},"links":{"a":{"from":"db","to":"dream","pts":["db","dream"],"heads":"end","label":"new msgs"},"b":{"from":"dream","to":"arch","pts":["dream","arch"],"heads":"end","label":"append"},"c":{"from":"dream","to":"llm","pts":["dream","llm"],"heads":"end","label":"distill"},"r1":{"from":"mem","to":"ctx","pts":["mem","ctx"],"heads":"end","style":"off","label":"recall"}},"flows":[{"route":["db","dream"],"kind":"write","rate":0.9},{"route":["dream","llm"],"kind":"res","rate":0.7}]}}]},"end-of-turn":{"id":"end-of-turn","title":"Knowing When You're Done","summary":"The hardest problem in voice isn't hearing — it's knowing when you finished. Turn-taking research, the 300 ms silence timer, post-roll grace, and the frontier of semantic end-of-turn detection.","minutes":10,"level":"advanced","metrics":["eot","falseEnds","respond","total"],"legend":[["msg","speech"],["req","text"],["res","tokens"],["kill","cancel"]],"goals":[{"text":"Why turn-taking gaps of ~200 ms make endpointing hard","step":3},{"text":"The failure modes: cutting early vs waiting too long","step":2},{"text":"The current mechanism: server-side VAD + 300 ms tail + 200 ms post-roll","step":5},{"text":"Partials are for the eyes; finals are for the brain","step":7},{"text":"The trade-off dial and the semantic EOT frontier","step":8}],"steps":[{"short":"The awkward pause","chapter":"setup","title":"The hardest problem in voice","body":["Hearing is solved. Knowing <b>when you finished</b> is not. A sentence has pauses inside it — “let me think… the code is” — and a system that mistakes a pause for the end will answer a half-question.","Seneschal's answer is a contract: a silence timer with grace, partials for the eyes, finals for the brain, and every behavior locked by named tests."],"callout":{"kind":"insight","text":"Turn-taking is the hardest problem in voice, and it is a timing problem, not a hearing one."},"metrics":{"eot":300,"falseEnds":null,"respond":null,"total":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"“let me think…”","icon":"hourglass"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"BT · 16 kHz"},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"server VAD"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"]}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","style":"off","label":"waits for final"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.4}]}},{"short":"Cut too early","chapter":"problem","title":"The half-question","body":["Set the silence timer too short and every thinking pause becomes a false end. You say “open the garage door… wait, the code is” — the endpointer hears 300 ms of silence, closes the turn, and the LLM confidently answers a question you hadn't finished.","Each false split costs two turns: one wrong answer, one repair."],"callout":{"kind":"insight","text":"A false split is worse than a slow reply: it produces confident nonsense."},"metrics":{"eot":200,"falseEnds":3,"respond":null,"total":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"interrupted!","tone":"red","icon":"alert"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"300 ms tail","tags":[{"text":"SPLIT","tone":"red","icon":"split"}]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"answering too soon","tags":[{"text":"HALF-Q","tone":"red","icon":"alert"}]},"half":{"type":"ghost","x":1,"y":9,"s":5,"h":40,"label":"“open the garage door” — the rest never arrived"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio frames"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"premature final"}},"flows":[{"route":["asr","llm"],"kind":"req","rate":0.8}]}},{"short":"Wait too long","chapter":"problem","title":"The dispreferred silence","body":["Swing the other way and the pause after your question stretches. Research on human conversation is blunt: gaps of 700 ms already read as a “dispreferred” — rejecting — answer, and the awkwardness is detectable from ~600 ms.","A butler that makes you wait a second and a half for a yes-or-no feels like it is deciding whether to bother."],"callout":{"kind":"insight","text":"Silence beyond ~700 ms is not neutral: humans read it as hesitation before a no."},"metrics":{"eot":900,"falseEnds":0,"respond":1900,"total":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"waiting…","tone":"red","icon":"hourglass"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"900 ms tail","tags":[{"text":"SLOW","tone":"amber","icon":"hourglass"}]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"still waiting"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"The wait, measured","lines":["silence tail           900 ms","post-roll grace        200 ms","+ Silero lag         100–200 ms","+ STT inference      450–950 ms","= transcript at      ~1.9 s","# you gave up at 1.2 s"],"icon":"timer"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","style":"off"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","style":"off","label":"…any moment"}},"flows":[]}},{"short":"What humans do","chapter":"insight","title":"Two hundred milliseconds","body":["Human between-turn gaps average <b>~200 ms</b> — far shorter than the 600+ ms it takes to produce a sentence. Listeners don't wait for silence; they <b>predict</b> the end of the turn from grammar and meaning.","Half of all gaps are under 200 ms, and gaps under 120 ms aren't even perceived as gaps. The machine's timer is playing a game humans win by prediction."],"callout":{"kind":"insight","text":"Humans predict the turn's end; the machine can only count silence. That is the gap to close."},"metrics":{"eot":300,"falseEnds":null,"respond":null,"total":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"human":{"type":"block","x":-6,"y":0,"color":"green","glyph":"users","label":["Humans"],"sub":"predict the end"},"asr":{"type":"block","x":1,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"counts silence"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"Turn-taking research","lines":["avg between-turn gap    ~200 ms","gaps under 200 ms       51–55 %","gaps under 500 ms       70–82 %","perceived gap           > 120 ms","dispreferred read       ≥ 700 ms","# predict, don't wait"],"icon":"users"}},"links":{"a":{"from":"human","to":"asr","pts":["human","asr"],"heads":"both","label":"same problem"}},"flows":[]}},{"short":"The silence timer","chapter":"technique","title":"Endpointing, server-side","body":["Seneschal streams PCM to a realtime ASR endpoint and the <b>VAD-driven endpointer lives server-side</b>: the configured tail (VAD_SILENCE_MS, 300 ms) is sent as endpointing_ms. When trailing silence outlasts it, the server emits the final transcript.","Keeping endpointing in the server means one implementation, tuned on real audio, shared by every client — and the client never guesses."],"callout":{"kind":"insight","text":"Endpointing is a policy, not a client hack. It lives where the audio lives."},"metrics":{"eot":300,"falseEnds":1,"respond":1200,"total":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"speaking…","icon":"waves"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR + VAD"],"sub":"server-side","tags":[{"text":"endpointing: 300 ms","tone":"amber","icon":"timer"}]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"waiting"},"tail":{"type":"ghost","x":-6,"y":9,"s":4,"h":40,"label":"trailing silence ≥ 300 ms → final"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"PCM 16 kHz"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","style":"off","label":"on final"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.6}]}},{"short":"Post-roll grace","chapter":"technique","title":"The comma rescue","body":["A bare silence timer would still split at every breath. The rescue is <b>post-roll</b>: 200 ms of grace after the timer fires, during which resumed speech cancels the closure and the turn continues.","The comma pause — “I'll take the usual… and also” — survives it. The audit found the old in-process segmenter quantized the tail into 200 ms probe windows, turning 300 ms into a real 400–600 ms close; the current server-side counter counts silence at the VAD's own resolution."],"callout":{"kind":"insight","text":"The tail decides sensitivity; the post-roll decides forgiveness. You need both."},"metrics":{"eot":300,"falseEnds":0,"respond":null,"total":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"“…and also”","icon":"message"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR + VAD"],"sub":"300 ms + 200 ms grace","tags":[{"text":"REOPENED","tone":"green","icon":"refresh"}]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"still waiting"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"both","label":"speech resumes"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.2,"bounce":true}]}},{"short":"Partials vs finals","chapter":"technique","title":"Two streams, two consumers","body":["The ASR emits two kinds of events and they must never be confused. <b>Partials</b> stream while you speak: they feed the live UI and act as the barge-in trigger. <b>Finals</b> (.completed) are the only thing that reaches the LLM.","And after a barge-in, results from the cancelled turn are <b>stale</b> — dropped by contract, never spoken. The whole behavior is locked by named audit tests, so swapping STT providers cannot silently break it."],"callout":{"kind":"insight","text":"Partials are for the eyes and the trigger finger. Finals are for the brain. Stale is a third category: dropped."},"metrics":{"eot":300,"falseEnds":0,"respond":900,"total":1500},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"2 event kinds"},"ui":{"type":"block","x":1,"y":-9,"color":"slate","glyph":"eye","label":["Live UI"],"sub":"partials"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"finals only"},"barge":{"type":"block","x":1,"y":9,"color":"red","glyph":"zap","label":["Barge-in"],"sub":"first partial"},"stale":{"type":"ghost","x":8,"y":0,"s":4,"h":44,"label":"stale finals → dropped"}},"links":{"p1":{"from":"asr","to":"ui","pts":["asr","ui"],"heads":"end","style":"off","label":"partials"},"p2":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"finals"},"p3":{"from":"asr","to":"barge","pts":["asr","barge"],"heads":"end","style":"cut","label":"first partial"}},"flows":[{"route":["asr","llm"],"kind":"res","rate":0.6},{"route":["asr","barge"],"kind":"kill","rate":0.3}]}},{"short":"The dial","chapter":"tradeoff","title":"200 ms is a lever, not a free lunch","body":["Shorten the tail to 200 ms and replies land with human rhythm — but the English comma-pause regression gets worse unless you pair it with better EOT. The industry cluster sits at 200–500 ms; Seneschal's canonical value is 300 ms with a 200 ms post-roll.","Every change to the dial must re-validate against the audit fixtures. The knob is the biggest single lever on perceived latency — and the easiest way to break the conversation."],"callout":{"kind":"insight","text":"The silence tail is one knob with two costs: reply latency and false splits. Tune it with tests, not vibes."},"metrics":{"eot":200,"falseEnds":3,"respond":800,"total":1400},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR + VAD"],"sub":"200 ms tail","tags":[{"text":"faster","tone":"green","icon":"trendingUp"},{"text":"riskier","tone":"amber","icon":"alert"}]},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"replies sooner"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"The dial","lines":["200 ms   human rhythm, more splits","300 ms   canonical + 200 ms post-roll","500 ms   safe, sluggish","industry cluster 200–500 ms","# re-validate the fixtures"],"icon":"filter"}},"links":{"a":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"final"}},"flows":[{"route":["asr","llm"],"kind":"res","rate":0.7}]}},{"short":"Semantic EOT","chapter":"technique","title":"Predict the end, like humans do","body":["The frontier is semantic end-of-turn: models like Parakeet-EOU read the <b>meaning</b> of the stream — “is this utterance complete?” — instead of counting silence. A trailing “because…” suppresses the endpoint no matter how long the pause; a finished question fires early.","That is the machine finally playing the same game humans play: prediction, not timing."],"callout":{"kind":"insight","text":"Silence is a proxy. Meaning is the signal."},"metrics":{"eot":250,"falseEnds":0,"respond":850,"total":1450},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR"],"sub":"stream"},"eou":{"type":"block","x":1,"y":0,"color":"violet","glyph":"bulb","label":["EOT model"],"sub":"semantic · 120 M","tags":[{"text":"“is it done?”","tone":"green","icon":"circleCheck"}]},"llm":{"type":"block","x":8,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"]}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio"},"b":{"from":"asr","to":"eou","pts":["asr","eou"],"heads":"end","label":"stream"},"c":{"from":"eou","to":"llm","pts":["eou","llm"],"heads":"end","label":"end of turn"}},"flows":[{"route":["asr","eou"],"kind":"res","rate":1},{"route":["eou","llm"],"kind":"req","rate":0.5}]}},{"short":"The contract","chapter":"insight","title":"Locked by named tests","body":["Everything above is a <b>contract</b>: partials open turns and trigger barge-in, finals gate the LLM, stale results are dropped, the tail plus post-roll closes turns. Each property is pinned by a named audit test.","Which is why Seneschal could swap its STT runtime — from an in-process Silero segmenter to a server-side Nemotron realtime endpoint — without rewriting the brain. The contract held; only the transport changed."],"callout":{"kind":"insight","text":"A contract is what lets you replace the ears without touching the brain."},"metrics":{"eot":300,"falseEnds":0,"respond":850,"total":1450},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR runtime"],"sub":"swappable","tags":[{"text":"Nemotron WS","tone":"green","icon":"refresh"}]},"contract":{"type":"block","x":1,"y":0,"color":"slate","glyph":"shield","label":["Contract"],"sub":"P1–P6 · audit tests"},"llm":{"type":"block","x":8,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"unaffected"}},"links":{"a":{"from":"asr","to":"contract","pts":["asr","contract"],"heads":"end","label":"must hold"},"b":{"from":"contract","to":"llm","pts":["contract","llm"],"heads":"end","label":"stable"}},"flows":[]}},{"short":"What we built","chapter":"recap","title":"The ears have a contract","body":["A 300 ms server-side silence tail, a 200 ms post-roll grace, partials that feed the UI and trigger barge-in, finals that gate the LLM, stale results dropped, and every property locked by audit tests — with semantic EOT as the research frontier.","The machine still can't predict like a human. But it can time honestly, forgive gently, and hold its contract while the ears get replaced underneath it."],"callout":{"kind":"insight","text":"Knowing when you're done is a contract, not a threshold."},"metrics":{"eot":300,"falseEnds":0,"respond":850,"total":1450},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"asr":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["ASR + VAD"],"sub":"300 ms · server-side"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"finals only"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"What we built","lines":["tail            300 ms · server-side","grace           200 ms post-roll","partials        UI + barge-in","finals          gate the LLM","stale           dropped","locks           named audit tests","# predict, don't just count"],"icon":"shield"}},"links":{"a":{"from":"mic","to":"asr","pts":["mic","asr"],"heads":"end","label":"audio"},"b":{"from":"asr","to":"llm","pts":["asr","llm"],"heads":"end","label":"finals"}},"flows":[{"route":["mic","asr"],"kind":"msg","rate":1.2},{"route":["asr","llm"],"kind":"res","rate":0.5}]}}]},"announcement-window":{"id":"announcement-window","title":"The Announcement Window","summary":"A butler must sometimes speak first — worker results, screen warnings, device alerts. The announcement window decides when speaking is welcome, folds everything into one locution, and keeps the conversation clean.","minutes":10,"level":"advanced","metrics":["pending","locutions","delay","respond"],"legend":[["msg","speech"],["write","event"],["res","tokens"],["kill","cancel"]],"goals":[{"text":"What proactive events exist and where they come from","step":1},{"text":"Why blurting out mid-sentence is the cardinal sin","step":2},{"text":"The window state machine: user speaking, turn pending, audio playing","step":3},{"text":"One result, one locution — never fragments","step":5},{"text":"The FIFO queue drains at natural gaps","step":8}],"steps":[{"short":"When nobody asked","chapter":"setup","title":"The butler speaks first","body":["Everything so far answered a question. But a butler also walks in and says: “the build failed”, “the disk is at 90 %”, “you have a meeting in five minutes”. These <b>proactive events</b> arrive from the deep worker, the screen watcher, the device monitor, long research.","The hard part is not generating them. It is choosing the moment to open your mouth."],"callout":{"kind":"insight","text":"A chatbot waits its turn. A butler owns a calendar of things you didn't ask — and must never step on yours."},"metrics":{"pending":null,"locutions":null,"delay":null,"respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"working","icon":"cpu"}]},"spk":{"type":"block","x":-6,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"win":{"type":"block","x":1,"y":0,"color":"slate","glyph":"inbox","label":["Announcement","Window"],"sub":"not yet"},"w1":{"type":"block","x":8,"y":-6,"color":"violet","glyph":"cpu","label":["Deep Worker"]},"w2":{"type":"block","x":8,"y":0,"color":"orange","glyph":"eye","label":["EYES"]},"w3":{"type":"block","x":8,"y":6,"color":"green","glyph":"activity","label":["Device","Monitor"]}},"links":{"e1":{"from":"w1","to":"win","pts":["w1","win"],"heads":"end","style":"off"},"e2":{"from":"w2","to":"win","pts":["w2","win"],"heads":"end","style":"off"},"e3":{"from":"w3","to":"win","pts":["w3","win"],"heads":"end","style":"off"}},"flows":[]}},{"short":"Blurting out","chapter":"problem","title":"The cardinal sin","body":["The naive implementation speaks the instant an event lands. You are mid-sentence — “remind me to call the…” — and the machine talks over you with a disk warning. Worse, a long result arrives in pieces: three fragments scattered across a minute, each one an interruption.","Nothing destroys trust in a voice interface faster than being talked over."],"callout":{"kind":"insight","text":"One interruption is information. Three is harassment."},"metrics":{"pending":0,"locutions":4,"delay":"1.2 s","respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"interrupted!","tone":"red","icon":"alert"}]},"spk":{"type":"block","x":-6,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"tags":[{"text":"TALKING","tone":"red","icon":"alert"}]},"win":{"type":"block","x":1,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"bypassed"},"w1":{"type":"block","x":8,"y":-6,"color":"violet","glyph":"cpu","label":["Deep Worker"]},"w2":{"type":"block","x":8,"y":0,"color":"orange","glyph":"eye","label":["EYES"]},"w3":{"type":"block","x":8,"y":6,"color":"green","glyph":"activity","label":["Device","Monitor"]}},"links":{"e1":{"from":"w1","to":"spk","pts":["w1","win","spk"],"heads":"end","style":"cut","label":"speaks now!"},"e2":{"from":"w2","to":"spk","pts":["w2","win","spk"],"heads":"end","style":"cut"},"e3":{"from":"w3","to":"spk","pts":["w3","win","spk"],"heads":"end","style":"cut"}},"flows":[{"route":["w1","win","spk"],"kind":"write","rate":0.9},{"route":["w2","win","spk"],"kind":"write","rate":0.7}]}},{"short":"The window","chapter":"insight","title":"A state machine for silence","body":["The fix is a tiny state machine that watches the conversation and knows when the mouth is free: is the <b>user speaking</b>? Is a <b>turn in flight</b> (transcript ready, LLM answering)? Is audio <b>queued or playing</b>?","Only when all four are clear does the window open. Everything else waits in a FIFO queue. The announcement is not an event — it is a moment, and the window knows when the moment arrives."],"callout":{"kind":"insight","text":"Proactive speech is scheduled by the conversation's own rhythm, not by the event's timestamp."},"metrics":{"pending":2,"locutions":null,"delay":"0 ms","respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"spk":{"type":"block","x":-6,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"sub":"silent"},"win":{"type":"block","x":1,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"watching","tags":[{"text":"user speaking ✓","tone":"amber","icon":"waves"},{"text":"turn pending ✓","tone":"amber","icon":"hourglass"}]},"queue":{"type":"ghost","x":1,"y":9,"s":5,"h":44,"label":"FIFO: [disk 90 %] [meeting in 5 min]"}},"links":{},"flows":[]}},{"short":"The gate","chapter":"technique","title":"Four checks before the mouth opens","body":["Every announcement passes the same gate: the user is <b>not speaking</b>, no <b>turn is pending</b>, no audio is <b>queued</b>, nothing is <b>playing</b>. SpeechStart closes the window; the moment the last audio finishes and the turn is done, it reopens and drains the queue.","The checks are cheap — a few booleans — but they encode the entire etiquette of the house."],"callout":{"kind":"insight","text":"Etiquette, compiled: four booleans stand between an event and your ear."},"metrics":{"pending":2,"locutions":null,"delay":"0 ms","respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"win":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"gate checks"},"gate":{"type":"ghost","x":1,"y":0,"s":5,"h":60,"label":"user speaking? turn pending? audio queued? playing?"},"spk":{"type":"block","x":8,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"sub":"opens when clear"}},"links":{"a":{"from":"win","to":"spk","pts":["win","spk"],"heads":"end","style":"off","label":"on gap"}},"flows":[]}},{"short":"One locution","chapter":"technique","title":"One result, one sentence","body":["When the window opens, the result is spoken as <b>one locution</b> — never fragments across turns, never a raw tool log. The event reaches the main LLM first, which reformulates it in Seneschal's own voice, sized for the ear.","The user asked in one sentence and gets one sentence back. The machinery — which model ran, which tool, how long — stays invisible."],"callout":{"kind":"insight","text":"One event, one sentence, in the butler's voice. Never a system log read aloud."},"metrics":{"pending":1,"locutions":1,"delay":"0 ms","respond":1500},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"win":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"open"},"llm":{"type":"block","x":1,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"reformulates","tags":[{"text":"in seneschal's voice","tone":"green","icon":"check"}]},"spk":{"type":"block","x":8,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"tags":[{"text":"ONE locution","tone":"green","icon":"volume2"}]},"raw":{"type":"ghost","x":1,"y":9,"s":5,"h":40,"label":"raw event: “exit code 1, build.rs, 2 warnings…”"}},"links":{"a":{"from":"win","to":"llm","pts":["win","llm"],"heads":"end","label":"event"},"b":{"from":"llm","to":"spk","pts":["llm","spk"],"heads":"end","label":"one sentence"}},"flows":[{"route":["win","llm"],"kind":"write","rate":0.7},{"route":["llm","spk"],"kind":"msg","rate":0.7}]}},{"short":"Interrupt discipline","chapter":"technique","title":"Speech interrupts announcements","body":["The moment you start talking, the window slams shut: SpeechStart calls interrupt() and any announcement that was queued or playing yields. Your speech outranks the machine's, always — the same rule as barge-in, applied to proactive speech.","Interrupted announcements are not lost. They return to the queue and try again at the next gap, possibly rephrased shorter."],"callout":{"kind":"insight","text":"You outrank the butler. The announcement yields and waits for a better moment."},"metrics":{"pending":1,"locutions":1,"delay":"0 ms","respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"interrupting!","tone":"red","icon":"alert"}]},"win":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"closed","tags":[{"text":"CLOSED","tone":"red","icon":"close"}]},"spk":{"type":"block","x":1,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"sub":"yields","tags":[{"text":"SILENT","tone":"green","icon":"check"}]},"queue":{"type":"ghost","x":1,"y":9,"s":5,"h":40,"label":"announcement returns to FIFO"}},"links":{"a":{"from":"you","to":"win","pts":["you","win"],"heads":"end","style":"cut","label":"SpeechStart"}},"flows":[{"route":["you","win"],"kind":"kill","rate":0.8}]}},{"short":"Freshness vs calm","chapter":"tradeoff","title":"Stale is better than noisy","body":["A device monitor pings every few seconds; the screen watcher finds things every minute. Announce everything the moment the window opens and the butler becomes a notification feed.","The compromise: the window drains at natural gaps, but <b>similar events collapse</b> — three disk warnings become one — and low-priority sources back off when they've been ignored. Stale information, delivered calmly, beats fresh information delivered constantly."],"callout":{"kind":"insight","text":"The butler's calendar is not the event bus. Priority and collapse live in between."},"metrics":{"pending":2,"locutions":1,"delay":"0 ms","respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"win":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"drains at gaps"},"p1":{"type":"ghost","x":1,"y":-8,"s":4,"h":36,"label":"disk 89 %"},"p2":{"type":"ghost","x":1,"y":0,"s":4,"h":36,"label":"disk 90 %"},"p3":{"type":"ghost","x":1,"y":8,"s":4,"h":36,"label":"disk 90 %…"},"one":{"type":"block","x":8,"y":0,"color":"sand","glyph":"volume2","label":["One warning"],"sub":"collapsed"}},"links":{"a":{"from":"win","to":"one","pts":["win","one"],"heads":"end","label":"collapse"}},"flows":[]}},{"short":"The queue","chapter":"technique","title":"FIFO drains at the next gap","body":["Three results land while you're mid-conversation. The window holds them in a FIFO: disk warning, meeting reminder, build result. Your turn ends, the last audio plays out — and the window drains them in order, each one locution, spaced so they breathe.","If you start talking again mid-drain, the remainder goes back to the queue. The queue is patient so you don't have to be."],"callout":{"kind":"insight","text":"The queue is patience made data: FIFO order, drained only in gaps."},"metrics":{"pending":0,"locutions":1,"delay":"0 ms","respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"listening","tone":"green","icon":"check"}]},"win":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"open","tags":[{"text":"draining","tone":"green","icon":"play"}]},"spk":{"type":"block","x":1,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"sub":"in order"},"q":{"type":"ghost","x":8,"y":0,"s":4,"h":44,"label":"FIFO empty ✓"}},"links":{"a":{"from":"win","to":"spk","pts":["win","spk"],"heads":"end","label":"one by one"}},"flows":[{"route":["win","spk"],"kind":"msg","rate":0.8}]}},{"short":"Never in the history","chapter":"insight","title":"Proactive ≠ conversational","body":["Announcements do not enter the speech history. They carry no tool identity, leave no transcript behind, and the next turn starts as if they never happened — unless you respond to one.","This keeps the context window clean (the model isn't confused by machine monologue) and keeps memory honest: the S-DREAM distiller sees a conversation, not a notification feed."],"callout":{"kind":"insight","text":"The butler's asides leave no footprints in the conversation."},"metrics":{"pending":0,"locutions":1,"delay":"0 ms","respond":1500},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"win":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"inbox","label":["Window"]},"hist":{"type":"block","x":1,"y":0,"color":"green","glyph":"layers","label":["Speech history"],"sub":"clean","tags":[{"text":"no footprints","tone":"green","icon":"circleCheck"}]},"dream":{"type":"block","x":8,"y":0,"color":"slate","glyph":"moon","label":["S-DREAM"],"sub":"sees a conversation"}},"links":{"a":{"from":"win","to":"hist","pts":["win","hist"],"heads":"end","style":"off","label":"bypasses"}},"flows":[]}},{"short":"The sources","chapter":"technique","title":"Who knocks on the window","body":["Four sources feed the window today. The <b>deep worker</b> delivering results. <b>EYES</b> flagging something urgent on screen. The <b>device monitor</b> with hardware signals. <b>Deep research</b> finishing a long query. Each arrives as the same proactive event; each gets the same etiquette.","New sources are one ProactiveEvent send away — which is exactly why the window must exist: the number of things that want to talk only grows."],"callout":{"kind":"insight","text":"Every future feature wants to speak. The window is how the house stays quiet."},"metrics":{"pending":0,"locutions":1,"delay":"0 ms","respond":1500},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"win":{"type":"block","x":1,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"one front door"},"w1":{"type":"block","x":9,"y":-9,"color":"violet","glyph":"cpu","label":["Deep Worker"]},"w2":{"type":"block","x":9,"y":-3,"color":"orange","glyph":"eye","label":["EYES"]},"w3":{"type":"block","x":9,"y":3,"color":"green","glyph":"activity","label":["Device","Monitor"]},"w4":{"type":"block","x":9,"y":9,"color":"blue","glyph":"search","label":["Deep","Research"]}},"links":{"e1":{"from":"w1","to":"win","pts":["w1","win"],"heads":"end"},"e2":{"from":"w2","to":"win","pts":["w2","win"],"heads":"end"},"e3":{"from":"w3","to":"win","pts":["w3","win"],"heads":"end"},"e4":{"from":"w4","to":"win","pts":["w4","win"],"heads":"end"}},"flows":[{"route":["w1","win"],"kind":"write","rate":0.4},{"route":["w2","win"],"kind":"write","rate":0.4}]}},{"short":"What we built","chapter":"recap","title":"Etiquette as a state machine","body":["A four-check gate, a FIFO queue, one locution per result, interrupts that yield to the user, collapsing duplicates, and a clean history. The machinery is small — a struct with five fields — but it is what makes the difference between a butler and a notification feed.","Anticipation without etiquette is spam. The announcement window is the etiquette."],"callout":{"kind":"insight","text":"Proactive speech is a scheduling problem. The window is the scheduler."},"metrics":{"pending":0,"locutions":1,"delay":"0 ms","respond":1500},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"win":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"gate · FIFO · 1 locution"},"spk":{"type":"block","x":1,"y":0,"color":"sand","glyph":"radio","label":["Speaker"]},"hist":{"type":"block","x":8,"y":0,"color":"green","glyph":"layers","label":["History"],"sub":"clean"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"What we built","lines":["gate       4 checks · booleans","queue      FIFO · drains at gaps","output     ONE locution, in voice","interrupt   SpeechStart yields it","history     no footprints","# anticipation with etiquette"],"icon":"inbox"}},"links":{"a":{"from":"win","to":"spk","pts":["win","spk"],"heads":"end","label":"at the gap"},"b":{"from":"win","to":"hist","pts":["win","hist"],"heads":"end","style":"off","label":"bypasses"}},"flows":[{"route":["win","spk"],"kind":"msg","rate":0.7}]}}]},"eyes":{"id":"eyes","title":"EYES — Visual Awareness","summary":"The third sense: a periodic silent screenshot, a conservative vision model, and a butler that tells you about the error dialog you can't see — without ever becoming a camera.","minutes":10,"level":"advanced","metrics":["interval","shots","fresh","util"],"legend":[["write","event"],["res","tokens"],["msg","speech"],["kill","cancel"]],"goals":[{"text":"Why a voice-only butler is blind to what you see","step":2},{"text":"The EYES loop: silent screenshot → vision LLM → structured verdict","step":4},{"text":"Conservatism as a prompt, not a filter","step":5},{"text":"Warnings pass through the butler's voice, not raw","step":6},{"text":"The interval dial: awareness vs GPU cost vs privacy","step":7}],"steps":[{"short":"The third sense","chapter":"setup","title":"A butler with its eyes closed","body":["Seneschal hears you (the voice pipeline), acts for you (tools and the deep worker) — and until now, saw nothing. You work all day with headphones on; an error dialog blooms on screen and the butler, literally, has no idea.","EYES is the third sense: a periodic, silent glance at your screen that speaks only when something deserves words."],"callout":{"kind":"insight","text":"Hearing, acting, seeing — a butler missing one of the three is half a butler."},"metrics":{"interval":"30 s","shots":null,"fresh":"stale","util":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"headphones on","icon":"volume2"}]},"ear":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Hearing"],"sub":"voice pipeline"},"hand":{"type":"block","x":-6,"y":0,"color":"orange","glyph":"hammer","label":["Acting"],"sub":"tools · worker"},"eye":{"type":"block","x":1,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"this lesson","tags":[{"text":"NEW","tone":"green","icon":"sparkles"}]}},"links":{},"flows":[]}},{"short":"Invisible errors","chapter":"problem","title":"The dialog you can't hear","body":["A build fails with a modal dialog. Your music is loud, your focus is deep, and twenty minutes pass before you alt-tab and find it. A voice-only assistant heard nothing — there was nothing to hear.","The failure mode is silence where a butler should have said: “the build just failed — it's the linking step.”"],"callout":{"kind":"insight","text":"The most important event of your hour may be visual-only."},"metrics":{"interval":"30 s","shots":null,"fresh":"stale","util":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"focused","icon":"target"}]},"screen":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"box","label":["Screen"],"sub":"error dialog","tags":[{"text":"ERROR","tone":"red","icon":"alert"}]},"ear":{"type":"block","x":1,"y":0,"color":"sand","glyph":"waves","label":["Hearing"],"sub":"nothing to hear","tags":[{"text":"DEAF","tone":"red","icon":"eyeOff"}]},"win":{"type":"ghost","x":1,"y":9,"s":5,"h":40,"label":"error dialog blooms — nobody sees it"}},"links":{},"flows":[]}},{"short":"Look, don't stare","chapter":"insight","title":"A glance, not a camera","body":["EYES is deliberately unambitious: every interval_secs it takes <b>one silent screenshot</b> — no video, no storage, no history — and asks a vision model a single question: is anything on this screen worth saying out loud right now?","One glance per interval keeps the module cheap, private and easy to reason about. It is a sentry, not a surveillance system."],"callout":{"kind":"insight","text":"One silent screenshot per interval. No video, no archive, no memory of what you had open."},"metrics":{"interval":"30 s","shots":12,"fresh":"stale","util":30},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"screen":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"box","label":["Screen"]},"eyes":{"type":"block","x":1,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"daemon","tags":[{"text":"every 30 s","tone":"amber","icon":"clock"}]},"cam":{"type":"ghost","x":1,"y":9,"s":4,"h":40,"label":"not a camera feed — one frame per interval"}},"links":{"a":{"from":"screen","to":"eyes","pts":["screen","eyes"],"heads":"end","label":"silent capture"}},"flows":[{"route":["screen","eyes"],"kind":"write","rate":0.6}]}},{"short":"The loop","chapter":"technique","title":"Screenshot → verdict","body":["The loop is three steps. Capture: a silent screenshot, no flash, no sound. Decide: the frame goes to the vision LLM with a fixed prompt. Answer: a structured verdict — warn_user: true|false, and an optional one-line message.","No pipeline stages, no parsers, no state. A daemon, a loop, a prompt — the simplest module in the house."],"callout":{"kind":"insight","text":"The whole module is: look, decide, (maybe) speak. Resist making it cleverer."},"metrics":{"interval":"30 s","shots":12,"fresh":"stale","util":30},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"eyes":{"type":"block","x":-6,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"daemon loop"},"vision":{"type":"block","x":1,"y":0,"color":"violet","glyph":"bot","label":["Vision LLM"],"sub":"multimodal"},"verdict":{"type":"block","x":8,"y":0,"color":"green","glyph":"circleCheck","label":["Verdict"],"sub":"warn_user?"}},"links":{"a":{"from":"eyes","to":"vision","pts":["eyes","vision"],"heads":"end","label":"frame + prompt"},"b":{"from":"vision","to":"verdict","pts":["vision","verdict"],"heads":"end","label":"structured answer"}},"flows":[{"route":["eyes","vision"],"kind":"write","rate":0.7},{"route":["vision","verdict"],"kind":"res","rate":0.7}]}},{"short":"Conservative by prompt","chapter":"technique","title":"The rules live in the prompt","body":["The vision model receives explicit rules: warn only for things <b>clearly important or time-sensitive</b> — error dialogs, warnings, deadlines, critical status. Never for normal app state, idle screens or routine content. If it warns, the message comes in the language visible on screen, one or two sentences.","No thresholds to tune, no classifiers to train. Conservatism is written in plain English and can be tightened the same way."],"callout":{"kind":"insight","text":"A well-prompted model beats a threshold. The rules are editable prose."},"metrics":{"interval":"30 s","shots":12,"fresh":"stale","util":30},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"vision":{"type":"block","x":-6,"y":0,"color":"violet","glyph":"bot","label":["Vision LLM"]},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"The prompt's rules","lines":["warn ONLY: errors, warnings,","  deadlines, critical status,","  clearly useful + time-sensitive","never: idle screens, routine","  app state, normal content","message: screen's language,","  1–2 short sentences"],"icon":"scroll"}},"links":{},"flows":[]}},{"short":"The butler's voice","chapter":"technique","title":"Warnings go through the house","body":["When the verdict is warn_user: true, the message does <b>not</b> go straight to the speaker. It becomes a proactive event, and the main assistant LLM reformulates it — in Seneschal's voice, sized for the ear — before handing it to the announcement window.","The result: “build's failed — looks like the linking step” instead of a vision model's raw caption. One house, one voice."],"callout":{"kind":"insight","text":"The watcher whispers to the butler; the butler speaks. One voice per house."},"metrics":{"interval":"30 s","shots":12,"fresh":"fresh","util":30},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"eyes":{"type":"block","x":-13,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"warn_user: true"},"llm":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"reformulates"},"win":{"type":"block","x":1,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"announcement"},"spk":{"type":"block","x":8,"y":0,"color":"sand","glyph":"radio","label":["Speaker"],"tags":[{"text":"ONE locution","tone":"green","icon":"volume2"}]}},"links":{"a":{"from":"eyes","to":"llm","pts":["eyes","llm"],"heads":"end","label":"ProactiveEvent"},"b":{"from":"llm","to":"win","pts":["llm","win"],"heads":"end","label":"in-house voice"},"c":{"from":"win","to":"spk","pts":["win","spk"],"heads":"end"}},"flows":[{"route":["eyes","llm"],"kind":"write","rate":0.6},{"route":["llm","win","spk"],"kind":"msg","rate":0.6}]}},{"short":"The dial","chapter":"tradeoff","title":"Every glance costs GPU","body":["The interval is a three-way trade. Every 5 seconds: genuinely aware, but the vision model runs constantly — utilization climbs, and on a box where the LLM owns a GPU, that contention is felt. Every 30 seconds: calm and useful. Off: free, and blind.","The right value depends on what the machine is doing. Awareness is a budget, and the interval is its dial."],"callout":{"kind":"insight","text":"Vigilance has a meter. The interval is where attention meets electricity."},"metrics":{"interval":"5 s","shots":120,"fresh":"fresh","util":65},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"eyes":{"type":"block","x":-6,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"every 5 s","tags":[{"text":"120 shots/h","tone":"amber","icon":"clock"}]},"vision":{"type":"block","x":1,"y":0,"color":"violet","glyph":"bot","label":["Vision LLM"],"sub":"65 % util","tags":[{"text":"contention","tone":"red","icon":"alert"}]},"llm":{"type":"block","x":8,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"feels the jitter"}},"links":{"a":{"from":"eyes","to":"vision","pts":["eyes","vision"],"heads":"end"},"b":{"from":"vision","to":"llm","pts":["vision","llm"],"heads":"end","style":"cut","label":"contends"}},"flows":[{"route":["eyes","vision"],"kind":"write","rate":1.2},{"route":["vision","llm"],"kind":"kill","rate":0.3}]}},{"short":"What counts","chapter":"technique","title":"A short list of urgencies","body":["In practice the verdicts cluster: build failures and crash dialogs, deadline reminders visible in a calendar tab, battery or disk warnings, a meeting about to start, an important message landing in a muted channel. Everything else — the hundred notifications a day — fails the conservatism test by design.","The list is short on purpose. A watchman who cries wolf once gets ignored forever."],"callout":{"kind":"insight","text":"EYES succeeds by what it doesn't say."},"metrics":{"interval":"30 s","shots":12,"fresh":"fresh","util":30},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"eyes":{"type":"block","x":-6,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"verdicts"},"ok":{"type":"ghost","x":1,"y":-9,"s":4,"h":36,"label":"idle screen → false"},"ok2":{"type":"ghost","x":1,"y":0,"s":4,"h":36,"label":"newsletter tab → false"},"urgent":{"type":"block","x":8,"y":0,"color":"red","glyph":"alert","label":["Build failed"],"sub":"→ true"}},"links":{"a":{"from":"eyes","to":"urgent","pts":["eyes","urgent"],"heads":"end","label":"speaks"}},"flows":[]}},{"short":"The gaze leaves home","chapter":"insight","title":"Privacy of the glance","body":["Every screenshot goes to the vision LLM — which may be a remote endpoint. Your screen, one frame at a time, leaves the machine. For some households that is fine; for others it is the whole conversation.","The design keeps the escape hatches honest: interval \"off\" closes the eyes completely, and a local multimodal model makes the gaze stay home. The default is a policy decision, not an implementation detail."],"callout":{"kind":"insight","text":"A butler who sees everything must be told whose eyes it borrows."},"metrics":{"interval":"off","shots":0,"fresh":"stale","util":0},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"private","icon":"key"}]},"eyes":{"type":"block","x":-6,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"eyes closed","tags":[{"text":"interval: off","tone":"amber","icon":"close"}]},"local":{"type":"block","x":1,"y":0,"color":"green","glyph":"cpu","label":["Local vision"],"sub":"gaze stays home"},"remote":{"type":"ghost","x":8,"y":0,"s":4,"h":44,"label":"remote endpoint — frames leave the house"}},"links":{"a":{"from":"eyes","to":"local","pts":["eyes","local"],"heads":"end","label":"option A"},"b":{"from":"eyes","to":"remote","pts":["eyes","remote"],"heads":"end","style":"off","label":"option B"}},"flows":[]}},{"short":"Not a camera","chapter":"technique","title":"Stateless glances","body":["A subtle design rule: EYES keeps <b>no state between glances</b>. No frame history, no per-app tracking, no accumulated profile of your day. Each screenshot is judged alone, the verdict is fired or discarded, and the loop sleeps.","Statelessness is what keeps it cheap, private and predictable — and what keeps it from creeping toward surveillance one feature at a time."],"callout":{"kind":"insight","text":"Every added memory of your screen is a small step toward being watched. EYES refuses the step."},"metrics":{"interval":"30 s","shots":12,"fresh":"fresh","util":30},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"eyes":{"type":"block","x":-6,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"stateless","tags":[{"text":"no frame history","tone":"green","icon":"check"}]},"verdict":{"type":"block","x":1,"y":0,"color":"green","glyph":"circleCheck","label":["Verdict"],"sub":"fire or discard"},"hist":{"type":"ghost","x":8,"y":0,"s":4,"h":44,"label":"no archive · no profile · no creep"}},"links":{"a":{"from":"eyes","to":"verdict","pts":["eyes","verdict"],"heads":"end"}},"flows":[{"route":["eyes","verdict"],"kind":"res","rate":0.6}]}},{"short":"What we built","chapter":"recap","title":"The butler has eyes","body":["A daemon with one clock and one prompt: silent screenshot every interval, a conservative structured verdict, warnings that travel through the butler's voice into the announcement window. Stateless, cheap, and easy to turn off.","Hearing, acting, seeing. The house is complete — and the eyes know when to stay closed."],"callout":{"kind":"insight","text":"The best watchman is the one you forget is there — until it matters."},"metrics":{"interval":"30 s","shots":12,"fresh":"fresh","util":30},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"ear":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Hearing"]},"hand":{"type":"block","x":-6,"y":0,"color":"orange","glyph":"hammer","label":["Acting"]},"eye":{"type":"block","x":1,"y":0,"color":"orange","glyph":"eye","label":["EYES"],"sub":"every 30 s · conservative"},"win":{"type":"block","x":8,"y":0,"color":"slate","glyph":"inbox","label":["Window"],"sub":"one locution"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"What we built","lines":["loop       screenshot → verdict","verdict    warn_user + message","voice      via main LLM · 1 locution","interval   5 s ↔ 30 s ↔ off","state      none — fire or discard","# see only what deserves words"],"icon":"eye"}},"links":{"a":{"from":"eye","to":"win","pts":["eye","win"],"heads":"end","label":"warnings"}},"flows":[{"route":["eye","win"],"kind":"write","rate":0.5}]}}]},"audio-ear":{"id":"audio-ear","title":"The Ear — Audio Internals","summary":"Before the words: 100 ms chunks, the descent to 16 kHz, the 300 ms pre-roll that saves your first syllable, ambient context, and the filler sound that makes thinking feel alive.","minutes":10,"level":"advanced","metrics":["rate","preroll","dropped","respond"],"legend":[["msg","audio"],["write","frames"],["res","text"],["kill","cancel"]],"goals":[{"text":"The capture path: CPAL chunks, mono, the pipeline heartbeat","step":2},{"text":"Why everything descends to 16 kHz mono for STT and VAD","step":3},{"text":"The pre-roll ring: why the first syllable exists","step":4},{"text":"Barge-in is a per-chunk cancel flag","step":7},{"text":"Why a butler plays a soft filler sound while thinking","step":9}],"steps":[{"short":"Before the words","chapter":"setup","title":"The journey of a sound","body":["Before any model runs, your voice is a pressure wave. It becomes voltage in the mic, samples in the driver, and then — inside Seneschal — a disciplined stream of chunks that the whole pipeline beats against.","This lesson follows that stream: capture, resampling, buffers, and the small kindnesses (pre-roll, filler) that make digital ears feel human."],"callout":{"kind":"insight","text":"Every upstream failure — drops, clipping, wrong rates — is invisible here and catastrophic everywhere else."},"metrics":{"rate":"48 kHz","preroll":null,"dropped":null,"respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"],"sub":"air → voltage"},"cpal":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"activity","label":["CPAL"],"sub":"capture"},"stt":{"type":"block","x":1,"y":0,"color":"blue","glyph":"signal","label":["STT · VAD"]}},"links":{"a":{"from":"mic","to":"cpal","pts":["mic","cpal"],"heads":"end","label":"I/O"},"b":{"from":"cpal","to":"stt","pts":["cpal","stt"],"heads":"end","label":"samples"}},"flows":[{"route":["mic","cpal"],"kind":"msg","rate":1.2},{"route":["cpal","stt"],"kind":"write","rate":1.2}]}},{"short":"100 ms chunks","chapter":"technique","title":"The heartbeat","body":["CPAL delivers audio in <b>100 ms chunks</b> — the heartbeat of the pipeline. Every chunk flows through the same path: gate, buffer, resample, VAD. Latency guarantees are made and kept at this granularity.","The same chunks carry the barge-in cancel flag: playback checks it between chunks, so interruption lands within one heartbeat — never mid-buffer."],"callout":{"kind":"insight","text":"The chunk is the quantum of the pipeline: latency, cancellation and buffering all happen in 100 ms steps."},"metrics":{"rate":"48 kHz","preroll":0,"dropped":null,"respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"cpal":{"type":"block","x":-13,"y":0,"color":"blue","glyph":"activity","label":["CPAL"],"sub":"100 ms chunks","tags":[{"text":"heartbeat","tone":"amber","icon":"activity"}]},"buf":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"database","label":["Ring buffer"]},"stt":{"type":"block","x":1,"y":0,"color":"blue","glyph":"signal","label":["STT · VAD"]}},"links":{"a":{"from":"cpal","to":"buf","pts":["cpal","buf"],"heads":"end","label":"chunks"},"b":{"from":"buf","to":"stt","pts":["buf","stt"],"heads":"end","label":"frames"}},"flows":[{"route":["cpal","buf"],"kind":"write","rate":1.6},{"route":["buf","stt"],"kind":"write","rate":1.6}]}},{"short":"16 kHz","chapter":"technique","title":"The descent to mono","body":["Your mic delivers 48 kHz stereo (or more). Speech models want <b>16 kHz mono</b> — so everything descends: a band-limited resampler (rubato) on the audio path, nearest-neighbour picking where VAD just needs energy.","Bluetooth gets a mention here too: HFP headsets deliver 16 kHz wideband or 8 kHz narrowband, and the profile you negotiate caps what the ear can ever hear. Garbage rate in, garbage transcript out."],"callout":{"kind":"insight","text":"Resampling is where pro audio meets telephony: 48 kHz in, 16 kHz out, no artifacts invited."},"metrics":{"rate":"16 kHz","preroll":0,"dropped":null,"respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"cpal":{"type":"block","x":-13,"y":0,"color":"blue","glyph":"activity","label":["CPAL"],"sub":"48 kHz stereo"},"rs":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"filter","label":["Resampler"],"sub":"rubato · band-limited","tags":[{"text":"→ 16 kHz mono","tone":"green","icon":"check"}]},"stt":{"type":"block","x":1,"y":0,"color":"blue","glyph":"signal","label":["STT · VAD"],"sub":"16 kHz mono"},"bt":{"type":"ghost","x":1,"y":9,"s":4,"h":40,"label":"HFP: 16 kHz wideband · 8 kHz narrowband"}},"links":{"a":{"from":"cpal","to":"rs","pts":["cpal","rs"],"heads":"end","label":"48 kHz"},"b":{"from":"rs","to":"stt","pts":["rs","stt"],"heads":"end","label":"16 kHz mono"}},"flows":[{"route":["cpal","rs"],"kind":"write","rate":1.4},{"route":["rs","stt"],"kind":"write","rate":1.4}]}},{"short":"The pre-roll","chapter":"technique","title":"300 ms before the trigger","body":["VAD fires <b>after</b> speech starts — by definition it is always late. The rescue is a <b>pre-roll ring buffer</b>: 300 ms of real audio kept continuously, so when the detector finally says “speech!”, the segment already contains the first syllable.","Seneschal keeps 300 ms of real audio in the ring (with a zero-pad fallback only when the ring is short). The pre-roll is the difference between “open the garage door” and “en the garage door”."],"callout":{"kind":"insight","text":"VAD is always late. The pre-roll is how the pipeline forgives it."},"metrics":{"rate":"16 kHz","preroll":300,"dropped":0,"respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"“o—”","icon":"waves"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"ring":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"database","label":["Pre-roll ring"],"sub":"300 ms real audio","tags":[{"text":"always full","tone":"green","icon":"circleCheck"}]},"vad":{"type":"block","x":1,"y":0,"color":"blue","glyph":"signal","label":["VAD"],"sub":"fires late"},"stt":{"type":"block","x":8,"y":0,"color":"blue","glyph":"signal","label":["STT"],"sub":"gets the whole word"}},"links":{"a":{"from":"mic","to":"ring","pts":["mic","ring"],"heads":"end","label":"always writing"},"b":{"from":"vad","to":"stt","pts":["vad","stt"],"heads":"end","label":"on speech"},"c":{"from":"ring","to":"stt","pts":["ring","stt"],"heads":"end","style":"off","label":"pre-roll attached"}},"flows":[{"route":["mic","ring"],"kind":"write","rate":1.6}]}},{"short":"The drop","chapter":"problem","title":"“…en the garage door”","body":["Without the pre-roll, the first phoneme dies in the gap between speech starting and VAD noticing. You say “open the garage door”; the transcript begins “…en the garage door”. The LLM does its best with a broken sentence, and you learn to over-enunciate — training yourself around your butler's deafness.","The fix cost 300 ms of buffer and one design decision. Without it, every utterance starts amputated."],"callout":{"kind":"insight","text":"Users never report a missing pre-roll. They just slowly stop trusting the ears."},"metrics":{"rate":"16 kHz","preroll":0,"dropped":1,"respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"over-enunciating","tone":"red","icon":"alert"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"vad":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"signal","label":["VAD"],"sub":"fires late","tags":[{"text":"300 ms late","tone":"red","icon":"hourglass"}]},"stt":{"type":"block","x":1,"y":0,"color":"blue","glyph":"signal","label":["STT"],"sub":"amputated transcript"},"lost":{"type":"ghost","x":1,"y":9,"s":5,"h":40,"label":"“o—” → gone. “open” arrives as “…en”"}},"links":{"a":{"from":"mic","to":"vad","pts":["mic","vad"],"heads":"end","style":"off"},"b":{"from":"vad","to":"stt","pts":["vad","stt"],"heads":"end","label":"late start"}},"flows":[]}},{"short":"Post-roll & ambient","chapter":"technique","title":"After the silence, context","body":["<arg_value>Two more buffers live downstream. The <b>post-roll</b> (200 ms) holds grace audio after VAD closes a turn — resumed speech cancels the closure. The <b>ambient buffer</b> keeps a longer slice of room tone for everything that isn't a command: speaker verification, wake-word gating, acoustic context for future features.","Not every buffer serves the transcript. Some serve the house."],"callout":{"kind":"insight","text":"Pre-roll catches the beginning. Post-roll forgives the end. Ambient remembers the room."},"metrics":{"rate":"16 kHz","preroll":300,"dropped":0,"respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"pre":{"type":"block","x":-13,"y":0,"color":"slate","glyph":"database","label":["Pre-roll"],"sub":"300 ms"},"post":{"type":"block","x":-6,"y":0,"color":"slate","glyph":"database","label":["Post-roll"],"sub":"200 ms grace"},"amb":{"type":"block","x":1,"y":0,"color":"green","glyph":"layers","label":["Ambient"],"sub":"room context","tags":[{"text":"speaker check · wake gate","tone":"amber","icon":"fingerprint"}]}},"links":{"a":{"from":"pre","to":"post","pts":["pre","post"],"heads":"end","style":"off"},"b":{"from":"post","to":"amb","pts":["post","amb"],"heads":"end","style":"off"}},"flows":[]}},{"short":"Barge-in plumbing","chapter":"technique","title":"Cancellation is a flag","body":["<arg_value>When you interrupt, there is no elegant shutdown — there is an atomic cancel flag, checked between every chunk on the playback path. The current chunk finishes; the rest of the queue evaporates; the next chunk belongs to the new turn.","The same flag pattern protects the TTS path and the capture path. Simple, lock-free, and fast enough that interruption feels instant."],"callout":{"kind":"insight","text":"Barge-in is not a subsystem. It is one boolean, checked at every heartbeat."},"metrics":{"rate":"16 kHz","preroll":300,"dropped":0,"respond":900},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"interrupting!","tone":"red","icon":"alert"}]},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Microphone"]},"flag":{"type":"block","x":-6,"y":0,"color":"red","glyph":"zap","label":["cancel flag"],"sub":"atomic","tags":[{"text":"checked per chunk","tone":"amber","icon":"activity"}]},"tts":{"type":"block","x":1,"y":0,"color":"orange","glyph":"volume2","label":["TTS queue"],"sub":"evaporates","tags":[{"text":"SILENT","tone":"green","icon":"check"}]}},"links":{"a":{"from":"mic","to":"flag","pts":["mic","flag"],"heads":"end","label":"SpeechStart"},"b":{"from":"flag","to":"tts","pts":["flag","tts"],"heads":"end","style":"cut","label":"stop"}},"flows":[{"route":["mic","flag"],"kind":"kill","rate":0.9},{"route":["flag","tts"],"kind":"kill","rate":0.9}]}},{"short":"The Bluetooth tax","chapter":"tradeoff","title":"Your headset decides your ears","body":["<arg_value>The weakest link in the ear is the last centimeter. Bluetooth HFP negotiates 16 kHz wideband — or 8 kHz narrowband — and cheap speakerphones deliver capture levels 20–40 dB below full scale, where VAD probabilities collapse. Seneschal normalizes each probe (quiet peaks are scaled up, capped) precisely because of this.","Buy the headset for its radio profile, not its battery. The transcript is only as good as the narrowest pipe it traveled through."],"callout":{"kind":"insight","text":"The model never hears your room. It hears what Bluetooth and a cheap ADC decided to keep."},"metrics":{"rate":"16 kHz","preroll":300,"dropped":0,"respond":null},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"BT headset","icon":"radio"}]},"bt":{"type":"block","x":-13,"y":0,"color":"slate","glyph":"radio","label":["HFP link"],"sub":"16 or 8 kHz","tags":[{"text":"the real ceiling","tone":"amber","icon":"alert"}]},"norm":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"gauge","label":["Normalize"],"sub":"peak → 0.5","tags":[{"text":"×500 cap","tone":"green","icon":"check"}]},"vad":{"type":"block","x":1,"y":0,"color":"blue","glyph":"signal","label":["VAD"],"sub":"now it can hear"}},"links":{"a":{"from":"bt","to":"norm","pts":["bt","norm"],"heads":"end","label":"quiet capture"},"b":{"from":"norm","to":"vad","pts":["norm","vad"],"heads":"end","label":"usable audio"}},"flows":[{"route":["bt","norm"],"kind":"write","rate":1.2},{"route":["norm","vad"],"kind":"write","rate":1.2}]}},{"short":"Filler sound","chapter":"insight","title":"The sound of thinking","body":["<arg_value>Here is a detail most systems miss: total silence while the butler thinks feels like death. Humans fill their thinking pauses with “mmh” — and Seneschal fills its own with a soft <b>background filler sound</b>, a gentle audio cue that says: I heard you, I'm on it.","It is psychoacoustics, not decoration. The filler bounds perceived waiting, covers the start of the reply, and turns a dead 1.5 s into a live one."],"callout":{"kind":"insight","text":"A pause filled with intent feels shorter than a shorter silence."},"metrics":{"rate":"16 kHz","preroll":300,"dropped":0,"respond":400},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you","tags":[{"text":"“mmh?”","icon":"message"}]},"spk":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"volume2","label":["Speaker"],"sub":"soft filler","tags":[{"text":"while thinking","tone":"green","icon":"play"}]},"llm":{"type":"block","x":-6,"y":0,"color":"purple","glyph":"bot","label":["Voice LLM"],"sub":"thinking…"},"tts":{"type":"block","x":1,"y":0,"color":"orange","glyph":"volume2","label":["First sentence"],"sub":"lands over the filler"}},"links":{"a":{"from":"spk","to":"llm","pts":["spk","llm"],"heads":"end","style":"off","label":"covers the gap"},"b":{"from":"llm","to":"tts","pts":["llm","tts"],"heads":"end","label":"reply"}},"flows":[{"route":["spk","llm"],"kind":"msg","rate":0.8},{"route":["llm","tts"],"kind":"res","rate":0.8}]}},{"short":"The full ear","chapter":"technique","title":"The chain, end to end","body":["<arg_value>The complete ear: air → microphone → CPAL (100 ms chunks) → resample to 16 kHz mono → pre-roll ring (always writing) → VAD (server-side) → STT → the contract. With ambient context, the cancel flag, and the filler sound living alongside.","Every stage is measurable, every handoff is buffered, and every buffer exists because a real utterance was once mangled without it."],"callout":{"kind":"insight","text":"Digital audio is a chain of buffers. A butler's ear is a chain of apologies for physics."},"metrics":{"rate":"16 kHz","preroll":300,"dropped":0,"respond":850},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Mic"],"sub":"48 kHz"},"cpal":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"activity","label":["CPAL"],"sub":"100 ms"},"rs":{"type":"block","x":1,"y":0,"color":"blue","glyph":"filter","label":["16 kHz"],"sub":"mono"},"ring":{"type":"block","x":8,"y":0,"color":"slate","glyph":"database","label":["Pre-roll"],"sub":"300 ms"},"vad":{"type":"block","x":15,"y":0,"color":"blue","glyph":"signal","label":["VAD"],"sub":"server-side"},"stt":{"type":"block","x":22,"y":0,"color":"blue","glyph":"signal","label":["STT"]}},"links":{"a":{"from":"mic","to":"cpal","pts":["mic","cpal"],"heads":"end"},"b":{"from":"cpal","to":"rs","pts":["cpal","rs"],"heads":"end"},"c":{"from":"rs","to":"ring","pts":["rs","ring"],"heads":"end"},"d":{"from":"ring","to":"vad","pts":["ring","vad"],"heads":"end"},"e":{"from":"vad","to":"stt","pts":["vad","stt"],"heads":"end","label":"whole word"}},"flows":[{"route":["mic","cpal","rs","ring"],"kind":"write","rate":1.4},{"route":["vad","stt"],"kind":"res","rate":0.5}]}},{"short":"What we built","chapter":"recap","title":"An ear worth trusting","body":["<arg_value>100 ms chunks, the descent to 16 kHz, a 300 ms pre-roll ring that saves every first syllable, 200 ms of post-roll grace, ambient context for the house, an atomic cancel flag for barge-in, probe normalization for cheap microphones, and a filler sound that makes thinking feel alive.","None of it is glamorous. All of it is why the transcript arrives complete — and why interruption feels like a conversation instead of a crash."],"callout":{"kind":"insight","text":"The ear is buffers all the way down. The craft is in what each buffer forgives."},"metrics":{"rate":"16 kHz","preroll":300,"dropped":0,"respond":850},"scene":{"entities":{"you":{"type":"device","x":-13,"y":-12,"form":"phone","w":5,"d":5,"label":"you"},"mic":{"type":"block","x":-13,"y":0,"color":"sand","glyph":"waves","label":["Mic"]},"cpal":{"type":"block","x":-6,"y":0,"color":"blue","glyph":"activity","label":["CPAL"],"sub":"100 ms chunks"},"rs":{"type":"block","x":1,"y":0,"color":"blue","glyph":"filter","label":["16 kHz"],"sub":"mono"},"ring":{"type":"block","x":8,"y":0,"color":"slate","glyph":"database","label":["Pre-roll"],"sub":"300 ms · always full"},"vad":{"type":"block","x":15,"y":0,"color":"blue","glyph":"signal","label":["VAD"],"sub":"+ post-roll 200 ms"},"stt":{"type":"block","x":22,"y":0,"color":"blue","glyph":"signal","label":["STT"],"sub":"→ the contract"},"card":{"type":"panel","x":0,"y":-12,"z":0,"dx":-175,"dy":-290,"title":"What we built","lines":["chunks      100 ms · the heartbeat","resample    48 → 16 kHz mono","pre-roll    300 ms · first syllable saved","post-roll   200 ms · comma forgiven","barge-in    atomic flag, per chunk","filler      the sound of thinking","# buffers all the way down"],"icon":"waves"}},"links":{"a":{"from":"mic","to":"cpal","pts":["mic","cpal"],"heads":"end"},"b":{"from":"cpal","to":"rs","pts":["cpal","rs"],"heads":"end"},"c":{"from":"rs","to":"ring","pts":["rs","ring"],"heads":"end"},"d":{"from":"ring","to":"vad","pts":["ring","vad"],"heads":"end"},"e":{"from":"vad","to":"stt","pts":["vad","stt"],"heads":"end","label":"whole words"}},"flows":[{"route":["mic","cpal","rs","ring"],"kind":"write","rate":1.2},{"route":["vad","stt"],"kind":"res","rate":0.5}]}}]}}};
